    navaids_point.aeronauticalgroundlight_t.colournilreason::text,
    -- embedded CodeYesNoType for getflashingitem,
    navaids_point.aeronauticalgroundlight_t.flashing::text,
    navaids_point.aeronauticalgroundlight_t.flashingnilreason::text,
    -- composed geometry AIXMElevatedPointPropertyType for location,
    aixm_elevated_point_pt_view_apvjpj.geom as location_geom,
    jsonb_build_object('hjid', aixm_elevated_point_pt_view_apvjpj.hjid,
    'id', aixm_elevated_point_pt_view_apvjpj.id,
    'horizontalaccuracy', aixm_elevated_point_pt_view_apvjpj.horizontalaccuracy,
    'horizontalaccuracy_uom', aixm_elevated_point_pt_view_apvjpj.horizontalaccuracy_uom,
    'horizontalaccuracy_nilreason', aixm_elevated_point_pt_view_apvjpj.horizontalaccuracy_nilreason,
    'geoidundulation', aixm_elevated_point_pt_view_apvjpj.geoidundulation,
    'geoidundulation_uom', aixm_elevated_point_pt_view_apvjpj.geoidundulation_uom,
    'geoidundulation_nilreason', aixm_elevated_point_pt_view_apvjpj.geoidundulation_nilreason,
    'verticalaccuracy', aixm_elevated_point_pt_view_apvjpj.verticalaccuracy,
    'verticalaccuracy_uom', aixm_elevated_point_pt_view_apvjpj.verticalaccuracy_uom,
    'verticalaccuracy_nilreason', aixm_elevated_point_pt_view_apvjpj.verticalaccuracy_nilreason,
    'elevation', aixm_elevated_point_pt_view_apvjpj.elevation,
    'elevation_uom', aixm_elevated_point_pt_view_apvjpj.elevation_uom,
    'elevation_nilreason', aixm_elevated_point_pt_view_apvjpj.elevation_nilreason) AS location,
    -- composed VerticalStructurePropertyType for structure_beacon,
    jsonb_build_object('href', verticalstructure_cxsitx.href,
    'nilreason', verticalstructure_cxsitx.nil_reason,
    'title', verticalstructure_cxsitx.simple_link_title) AS structure_beacon,
    -- composed AirportHeliportPropertyType for aerodrome_beacon,
    jsonb_build_object('href', airportheliport_cpbuqe.href,
    'nilreason', airportheliport_cpbuqe.nil_reason,
    'title', airportheliport_cpbuqe.simple_link_title) AS aerodrome_beacon,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from navaids_point.arntclgrndlghttmslctp_annttn_link join aixm.aixm_property on navaids_point.arntclgrndlghttmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where navaids_point.aeronauticalgroundlight_t.hjid = navaids_point.arntclgrndlghttmslctp_annttn_link.aeronauticalgroundlight_t_hjid ) as annotation
from aixm.aixm_feature
inner join navaids_point.aeronauticalgroundlight_f on aixm.aixm_feature.hjid = navaids_point.aeronauticalgroundlight_f.hjid
inner join navaids_point.aeronauticalgroundlight_tp on aixm.aixm_feature.hjid = navaids_point.aeronauticalgroundlight_tp.timeslice_hjid
inner join navaids_point.aeronauticalgroundlight_t on navaids_point.aeronauticalgroundlight_tp.aeronauticalgroundlighttimeslice_hjid = navaids_point.aeronauticalgroundlight_t.hjid
inner join aixm.aixm_timeslice on navaids_point.aeronauticalgroundlight_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed VerticalStructurePropertyType for structure_beacon
left join navaids_point.arntclgrndlghttmslctp_strctrbcn_link navaids_point_mtdczj on navaids_point.aeronauticalgroundlight_t.hjid = navaids_point_mtdczj.aeronauticalgroundlight_t_hjid
left join obstacle.verticalstructure_p verticalstructure_cxsitx on navaids_point_mtdczj.structurebeacon_hjid = verticalstructure_cxsitx.hjid
-- composed AirportHeliportPropertyType for aerodrome_beacon
left join navaids_point.arntclgrndlghttmslctp_ardrmbcn_link navaids_point_xlqyxs on navaids_point.aeronauticalgroundlight_t.hjid = navaids_point_xlqyxs.aeronauticalgroundlight_t_hjid
left join airport_heliport.airportheliport_p airportheliport_cpbuqe on navaids_point_xlqyxs.aerodromebeacon_hjid = airportheliport_cpbuqe.hjid
-- composed AIXMElevatedPointPropertyType for location
left join navaids_point.arntclgrndlghttmslctp_lctn_link navaids_point_jmiosp on navaids_point.aeronauticalgroundlight_t.hjid = navaids_point_jmiosp.aeronauticalgroundlight_t_hjid
left join gml.aixm_elevated_point_pt_view aixm_elevated_point_pt_view_apvjpj on navaids_point_jmiosp.location_hjid = aixm_elevated_point_pt_view_apvjpj.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;;

