    'id', aixm_elevated_point_pt_view_sogcyv.id,
    'horizontalaccuracy', aixm_elevated_point_pt_view_sogcyv.horizontalaccuracy,
    'horizontalaccuracy_uom', aixm_elevated_point_pt_view_sogcyv.horizontalaccuracy_uom,
    'horizontalaccuracy_nilreason', aixm_elevated_point_pt_view_sogcyv.horizontalaccuracy_nilreason,
