    -- composed UnitPropertyType for service_provider,
    jsonb_build_object('href', unit_tlnjxm.href,
    'nilreason', unit_tlnjxm.nil_reason,
    'title', unit_tlnjxm.simple_link_title) AS service_provider,
    -- composed RadioCommunicationChannelPropertyType for radio_communication,
