    'title', service.radiocommunicationchannel_p.simple_link_title)),'[]'::jsonb) from service.arcrftgrndsrvctmslctp_rdcmmnctn_link join service.radiocommunicationchannel_p on service.arcrftgrndsrvctmslctp_rdcmmnctn_link.radiocommunication_hjid = service.radiocommunicationchannel_p.hjid where service.aircraftgroundservice_t.hjid = service.arcrftgrndsrvctmslctp_rdcmmnctn_link.aircraftgroundservice_t_hjid ) as radio_communication,
