    -- composed ServiceOperationalStatusPropertyType for availability,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from service.arcrftgrndsrvctmslctp_avlblt_link join aixm.aixm_property on service.arcrftgrndsrvctmslctp_avlblt_link.availability_hjid = aixm.aixm_property.hjid where service.aircraftgroundservice_t.hjid = service.arcrftgrndsrvctmslctp_avlblt_link.aircraftgroundservice_t_hjid ) as availability,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from service.arcrftgrndsrvctmslctp_annttn_link join aixm.aixm_property on service.arcrftgrndsrvctmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where service.aircraftgroundservice_t.hjid = service.arcrftgrndsrvctmslctp_annttn_link.aircraftgroundservice_t_hjid ) as annotation,
