    -- embedded CodeFlightDestinationType for getflightoperationsitem,
    service.airtrafficcontrolservice_t.flightoperations::text,
    service.airtrafficcontrolservice_t.flightoperationsnilreason::text,
    -- embedded CodeFacilityRankingType for getrankitem,
    service.airtrafficcontrolservice_t.rank::text,
    service.airtrafficcontrolservice_t.ranknilreason::text,
    -- embedded CodeYesNoType for getcomplianticaoitem,
    service.airtrafficcontrolservice_t.complianticao::text,
    service.airtrafficcontrolservice_t.complianticaonilreason::text,
    -- embedded TextNameType for getaixmnameitem,
    service.airtrafficcontrolservice_t.name::text,
    service.airtrafficcontrolservice_t.namenilreason::text,
    -- embedded CodeYesNoType for getradarassisteditem,
    service.airtrafficcontrolservice_t.radarassisted::text,
    service.airtrafficcontrolservice_t.radarassistednilreason::text,
    -- embedded CodeYesNoType for getdatalinkenableditem,
    service.airtrafficcontrolservice_t.datalinkenabled::text,
    service.airtrafficcontrolservice_t.datalinkenablednilreason::text,
    -- embedded CodeCommunicationChannelType for getdatalinkchannelitem,
    service.airtrafficcontrolservice_t.datalinkchannel::text,
    service.airtrafficcontrolservice_t.datalinkchannelnilreason::text,
    -- embedded CodeServiceATCType for gettypeitem,
    service.airtrafficcontrolservice_t.type::text,
    service.airtrafficcontrolservice_t.typenilreason::text,
    -- composed geometry AIXMElevatedPointPropertyType for location,
    aixm_elevated_point_pt_view_lnifpa.geom as location_geom,
    jsonb_build_object('hjid', aixm_elevated_point_pt_view_lnifpa.hjid,
    'id', aixm_elevated_point_pt_view_lnifpa.id,
    'horizontalaccuracy', aixm_elevated_point_pt_view_lnifpa.horizontalaccuracy,
    'horizontalaccuracy_uom', aixm_elevated_point_pt_view_lnifpa.horizontalaccuracy_uom,
    'horizontalaccuracy_nilreason', aixm_elevated_point_pt_view_lnifpa.horizontalaccuracy_nilreason,
    'geoidundulation', aixm_elevated_point_pt_view_lnifpa.geoidundulation,
    'geoidundulation_uom', aixm_elevated_point_pt_view_lnifpa.geoidundulation_uom,
    'geoidundulation_nilreason', aixm_elevated_point_pt_view_lnifpa.geoidundulation_nilreason,
    'verticalaccuracy', aixm_elevated_point_pt_view_lnifpa.verticalaccuracy,
    'verticalaccuracy_uom', aixm_elevated_point_pt_view_lnifpa.verticalaccuracy_uom,
    'verticalaccuracy_nilreason', aixm_elevated_point_pt_view_lnifpa.verticalaccuracy_nilreason,
    'elevation', aixm_elevated_point_pt_view_lnifpa.elevation,
    'elevation_uom', aixm_elevated_point_pt_view_lnifpa.elevation_uom,
    'elevation_nilreason', aixm_elevated_point_pt_view_lnifpa.elevation_nilreason) AS location,
    -- composed UnitPropertyType for service_provider,
    jsonb_build_object('href', unit_wzkwrq.href,
    'nilreason', unit_wzkwrq.nil_reason,
    'title', unit_wzkwrq.simple_link_title) AS service_provider,
    -- composed DirectionFinderPropertyType for aircraft_locator,
    jsonb_build_object('href', directionfinder_xsqmeh.href,
    'nilreason', directionfinder_xsqmeh.nil_reason,
    'title', directionfinder_xsqmeh.simple_link_title) AS aircraft_locator,
    -- composed RadioCommunicationChannelPropertyType for radio_communication,
    (select coalesce(jsonb_agg(jsonb_build_object('href', service.radiocommunicationchannel_p.href,
    'nilreason', service.radiocommunicationchannel_p.nil_reason,
    'title', service.radiocommunicationchannel_p.simple_link_title)),'[]'::jsonb) from service.artrffccntrlsrvctmslctp_rdcmmnctn_link join service.radiocommunicationchannel_p on service.artrffccntrlsrvctmslctp_rdcmmnctn_link.radiocommunication_hjid = service.radiocommunicationchannel_p.hjid where service.airtrafficcontrolservice_t.hjid = service.artrffccntrlsrvctmslctp_rdcmmnctn_link.airtrafficcontrolservice_t_hjid ) as radio_communication,
    -- composed ContactInformationPropertyType for ground_communication,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from service.artrffccntrlsrvctmslctp_grndcmmnctn_link join aixm.aixm_property on service.artrffccntrlsrvctmslctp_grndcmmnctn_link.groundcommunication_hjid = aixm.aixm_property.hjid where service.airtrafficcontrolservice_t.hjid = service.artrffccntrlsrvctmslctp_grndcmmnctn_link.airtrafficcontrolservice_t_hjid ) as ground_communication,
    -- composed ServiceOperationalStatusPropertyType for availability,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from service.artrffccntrlsrvctmslctp_avlblt_link join aixm.aixm_property on service.artrffccntrlsrvctmslctp_avlblt_link.availability_hjid = aixm.aixm_property.hjid where service.airtrafficcontrolservice_t.hjid = service.artrffccntrlsrvctmslctp_avlblt_link.airtrafficcontrolservice_t_hjid ) as availability,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from service.artrffccntrlsrvctmslctp_annttn_link join aixm.aixm_property on service.artrffccntrlsrvctmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where service.airtrafficcontrolservice_t.hjid = service.artrffccntrlsrvctmslctp_annttn_link.airtrafficcontrolservice_t_hjid ) as annotation,
    -- composed AirportHeliportPropertyType for client_airport,
    (select coalesce(jsonb_agg(jsonb_build_object('href', airport_heliport.airportheliport_p.href,
    'nilreason', airport_heliport.airportheliport_p.nil_reason,
    'title', airport_heliport.airportheliport_p.simple_link_title)),'[]'::jsonb) from service.artrffccntrlsrvctmslctp_clntarprt_link join airport_heliport.airportheliport_p on service.artrffccntrlsrvctmslctp_clntarprt_link.clientairport_hjid = airport_heliport.airportheliport_p.hjid where service.airtrafficcontrolservice_t.hjid = service.artrffccntrlsrvctmslctp_clntarprt_link.airtrafficcontrolservice_t_hjid ) as client_airport,
    -- composed AirspacePropertyType for client_airspace,
    (select coalesce(jsonb_agg(jsonb_build_object('href', airspace.airspace_p.href,
    'nilreason', airspace.airspace_p.nil_reason,
    'title', airspace.airspace_p.simple_link_title)),'[]'::jsonb) from service.artrffccntrlsrvctmslctp_clntarspc_link join airspace.airspace_p on service.artrffccntrlsrvctmslctp_clntarspc_link.clientairspace_hjid = airspace.airspace_p.hjid where service.airtrafficcontrolservice_t.hjid = service.artrffccntrlsrvctmslctp_clntarspc_link.airtrafficcontrolservice_t_hjid ) as client_airspace,
    -- composed RoutePortionPropertyType for client_route,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from service.artrffccntrlsrvctmslctp_clntrt_link join aixm.aixm_property on service.artrffccntrlsrvctmslctp_clntrt_link.clientroute_hjid = aixm.aixm_property.hjid where service.airtrafficcontrolservice_t.hjid = service.artrffccntrlsrvctmslctp_clntrt_link.airtrafficcontrolservice_t_hjid ) as client_route,
    -- composed ProcedurePropertyType for client_procedure,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from service.artrffccntrlsrvctmslctp_clntprcdr_link join aixm.aixm_property on service.artrffccntrlsrvctmslctp_clntprcdr_link.clientprocedure_hjid = aixm.aixm_property.hjid where service.airtrafficcontrolservice_t.hjid = service.artrffccntrlsrvctmslctp_clntprcdr_link.airtrafficcontrolservice_t_hjid ) as client_procedure,
    -- composed HoldingPatternPropertyType for client_holding,
    (select coalesce(jsonb_agg(jsonb_build_object('href', holding.holdingpattern_p.href,
    'nilreason', holding.holdingpattern_p.nil_reason,
    'title', holding.holdingpattern_p.simple_link_title)),'[]'::jsonb) from service.artrffccntrlsrvctmslctp_clnthldng_link join holding.holdingpattern_p on service.artrffccntrlsrvctmslctp_clnthldng_link.clientholding_hjid = holding.holdingpattern_p.hjid where service.airtrafficcontrolservice_t.hjid = service.artrffccntrlsrvctmslctp_clnthldng_link.airtrafficcontrolservice_t_hjid ) as client_holding,
    -- composed AerialRefuellingPropertyType for client_aerial_refuelling,
    (select coalesce(jsonb_agg(jsonb_build_object('href', aerial_refuelling.aerialrefuelling_p.href,
    'nilreason', aerial_refuelling.aerialrefuelling_p.nil_reason,
    'title', aerial_refuelling.aerialrefuelling_p.simple_link_title)),'[]'::jsonb) from service.artrffccntrlsrvctmslctp_clntarlrfllng_link join aerial_refuelling.aerialrefuelling_p on service.artrffccntrlsrvctmslctp_clntarlrfllng_link.clientaerialrefuelling_hjid = aerial_refuelling.aerialrefuelling_p.hjid where service.airtrafficcontrolservice_t.hjid = service.artrffccntrlsrvctmslctp_clntarlrfllng_link.airtrafficcontrolservice_t_hjid ) as client_aerial_refuelling
from aixm.aixm_feature
inner join service.airtrafficcontrolservice_f on aixm.aixm_feature.hjid = service.airtrafficcontrolservice_f.hjid
inner join service.airtrafficcontrolservice_tp on aixm.aixm_feature.hjid = service.airtrafficcontrolservice_tp.timeslice_hjid
inner join service.airtrafficcontrolservice_t on service.airtrafficcontrolservice_tp.airtrafficcontrolservicetimeslice_hjid = service.airtrafficcontrolservice_t.hjid
inner join aixm.aixm_timeslice on service.airtrafficcontrolservice_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed AIXMElevatedPointPropertyType for location
left join service.artrffccntrlsrvctmslctp_lctn_link service_whfazd on service.airtrafficcontrolservice_t.hjid = service_whfazd.airtrafficcontrolservice_t_hjid
left join gml.aixm_elevated_point_pt_view aixm_elevated_point_pt_view_lnifpa on service_whfazd.location_hjid = aixm_elevated_point_pt_view_lnifpa.hjid
-- composed UnitPropertyType for service_provider
left join service.artrffccntrlsrvctmslctp_srvcprvdr_link service_qewhzc on service.airtrafficcontrolservice_t.hjid = service_qewhzc.airtrafficcontrolservice_t_hjid
left join organisation.unit_p unit_wzkwrq on service_qewhzc.serviceprovider_hjid = unit_wzkwrq.hjid
-- composed DirectionFinderPropertyType for aircraft_locator
left join service.artrffccntrlsrvctmslctp_arcrftlctr_link service_rspcps on service.airtrafficcontrolservice_t.hjid = service_rspcps.airtrafficcontrolservice_t_hjid
left join navaids_point.directionfinder_p directionfinder_xsqmeh on service_rspcps.aircraftlocator_hjid = directionfinder_xsqmeh.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;;

