    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from service.artrffcmngmntsrvctmslctp_grndcmmnctn_link join aixm.aixm_property on service.artrffcmngmntsrvctmslctp_grndcmmnctn_link.groundcommunication_hjid = aixm.aixm_property.hjid where service.airtrafficmanagementservice_t.hjid = service.artrffcmngmntsrvctmslctp_grndcmmnctn_link.airtrafficmanagementservice_t_hjid ) as ground_communication,
    -- composed ServiceOperationalStatusPropertyType for availability,
