    -- composed AirspacePropertyType for client_airspace,
    (select coalesce(jsonb_agg(jsonb_build_object('href', airspace.airspace_p.href,
    'nilreason', airspace.airspace_p.nil_reason,
    'title', airspace.airspace_p.simple_link_title)),'[]'::jsonb) from service.artrffcmngmntsrvctmslctp_clntarspc_link join airspace.airspace_p on service.artrffcmngmntsrvctmslctp_clntarspc_link.clientairspace_hjid = airspace.airspace_p.hjid where service.airtrafficmanagementservice_t.hjid = service.artrffcmngmntsrvctmslctp_clntarspc_link.airtrafficmanagementservice_t_hjid ) as client_airspace,
    -- composed AerialRefuellingPropertyType for client_aerial_refuelling,
    (select coalesce(jsonb_agg(jsonb_build_object('href', aerial_refuelling.aerialrefuelling_p.href,
