    'title', aerial_refuelling.aerialrefuelling_p.simple_link_title)),'[]'::jsonb) from service.artrffcmngmntsrvctmslctp_clntarlrfllng_link join aerial_refuelling.aerialrefuelling_p on service.artrffcmngmntsrvctmslctp_clntarlrfllng_link.clientaerialrefuelling_hjid = aerial_refuelling.aerialrefuelling_p.hjid where service.airtrafficmanagementservice_t.hjid = service.artrffcmngmntsrvctmslctp_clntarlrfllng_link.airtrafficmanagementservice_t_hjid ) as client_aerial_refuelling,
    -- composed RoutePortionPropertyType for client_route,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from service.artrffcmngmntsrvctmslctp_clntrt_link join aixm.aixm_property on service.artrffcmngmntsrvctmslctp_clntrt_link.clientroute_hjid = aixm.aixm_property.hjid where service.airtrafficmanagementservice_t.hjid = service.artrffcmngmntsrvctmslctp_clntrt_link.airtrafficmanagementservice_t_hjid ) as client_route
