    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from navaids_point.azmthtmslctp_annttn_link join aixm.aixm_property on navaids_point.azmthtmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where navaids_point.azimuth_t.hjid = navaids_point.azmthtmslctp_annttn_link.azimuth_t_hjid ) as annotation
from aixm.aixm_feature
