    COALESCE(aixm.aixm_timeslice.valid_time_end, '2100-01-01T00:00:00Z') AS valid_time_end,
    -- embedded ValDistanceType for getdistanceitem,
    route.changeoverpoint_t.distance::text,
    route.changeoverpoint_t.distanceuom::text,
    route.changeoverpoint_t.distancenilreason::text,
    -- composed geometry AIXMPointPropertyType for location_position,
    aixm_point_pt_view_iwfecu.geom as location_position_geom,
    jsonb_build_object('hjid', aixm_point_pt_view_iwfecu.hjid,
    'id', aixm_point_pt_view_iwfecu.id,
    'horizontalaccuracy', aixm_point_pt_view_iwfecu.horizontalaccuracy,
    'horizontalaccuracy_uom', aixm_point_pt_view_iwfecu.horizontalaccuracy_uom,
    'horizontalaccuracy_nilreason', aixm_point_pt_view_iwfecu.horizontalaccuracy_nilreason) AS location_position,
    -- composed DesignatedPointPropertyType for location_fix_designated_point,
    jsonb_build_object('href', designatedpoint_ahaqaa.href,
    'nilreason', designatedpoint_ahaqaa.nil_reason,
    'title', designatedpoint_ahaqaa.simple_link_title) AS location_fix_designated_point,
    -- composed NavaidPropertyType for location_navaid_system,
    jsonb_build_object('href', navaid_fgzhpc.href,
    'nilreason', navaid_fgzhpc.nil_reason,
    'title', navaid_fgzhpc.simple_link_title) AS location_navaid_system,
    -- composed TouchDownLiftOffPropertyType for location_aiming_point,
    jsonb_build_object('href', touchdownliftoff_pvtdsm.href,
    'nilreason', touchdownliftoff_pvtdsm.nil_reason,
    'title', touchdownliftoff_pvtdsm.simple_link_title) AS location_aiming_point,
    -- composed RunwayCentrelinePointPropertyType for location_runway_point,
    jsonb_build_object('href', runwaycentrelinepoint_dbbyct.href,
    'nilreason', runwaycentrelinepoint_dbbyct.nil_reason,
    'title', runwaycentrelinepoint_dbbyct.simple_link_title) AS location_runway_point,
    -- composed AirportHeliportPropertyType for location_airport_reference_point,
    jsonb_build_object('href', airportheliport_uuxeua.href,
    'nilreason', airportheliport_uuxeua.nil_reason,
    'title', airportheliport_uuxeua.simple_link_title) AS location_airport_reference_point,
    -- composed RoutePortionPropertyType for applicable_route_portion,
    jsonb_build_object('hjid', aixm_property_unoacd.hjid,
    'nilreason', aixm_property_unoacd.nil_reason) AS applicable_route_portion,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from route.chngovrpnttmslctp_annttn_link join aixm.aixm_property on route.chngovrpnttmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where route.changeoverpoint_t.hjid = route.chngovrpnttmslctp_annttn_link.changeoverpoint_t_hjid ) as annotation
from aixm.aixm_feature
inner join route.changeoverpoint_f on aixm.aixm_feature.hjid = route.changeoverpoint_f.hjid
inner join route.changeoverpoint_tp on aixm.aixm_feature.hjid = route.changeoverpoint_tp.timeslice_hjid
inner join route.changeoverpoint_t on route.changeoverpoint_tp.changeoverpointtimeslice_hjid = route.changeoverpoint_t.hjid
inner join aixm.aixm_timeslice on route.changeoverpoint_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed DesignatedPointPropertyType for location_fix_designated_point
left join route.chngovrpnttmslctp_lctnfxdsgntdpnt_link route_ietfqp on route.changeoverpoint_t.hjid = route_ietfqp.changeoverpoint_t_hjid
left join navaids_point.designatedpoint_p designatedpoint_ahaqaa on route_ietfqp.locationfixdesignatedpoint_hjid = designatedpoint_ahaqaa.hjid
-- composed NavaidPropertyType for location_navaid_system
left join route.chngovrpnttmslctp_lctnnvdsstm_link route_bsjkud on route.changeoverpoint_t.hjid = route_bsjkud.changeoverpoint_t_hjid
left join navaids_point.navaid_p navaid_fgzhpc on route_bsjkud.locationnavaidsystem_hjid = navaid_fgzhpc.hjid
-- composed TouchDownLiftOffPropertyType for location_aiming_point
left join route.chngovrpnttmslctp_lctnamngpnt_link route_tbnbok on route.changeoverpoint_t.hjid = route_tbnbok.changeoverpoint_t_hjid
left join airport_heliport.touchdownliftoff_p touchdownliftoff_pvtdsm on route_tbnbok.locationaimingpoint_hjid = touchdownliftoff_pvtdsm.hjid
-- composed RunwayCentrelinePointPropertyType for location_runway_point
left join route.chngovrpnttmslctp_lctnrnwpnt_link route_ckcbig on route.changeoverpoint_t.hjid = route_ckcbig.changeoverpoint_t_hjid
left join airport_heliport.runwaycentrelinepoint_p runwaycentrelinepoint_dbbyct on route_ckcbig.locationrunwaypoint_hjid = runwaycentrelinepoint_dbbyct.hjid
-- composed AirportHeliportPropertyType for location_airport_reference_point
left join route.chngovrpnttmslctp_lctnarprtrfrncpnt_link route_rntwsu on route.changeoverpoint_t.hjid = route_rntwsu.changeoverpoint_t_hjid
left join airport_heliport.airportheliport_p airportheliport_uuxeua on route_rntwsu.locationairportreferencepoint_hjid = airportheliport_uuxeua.hjid
-- composed AIXMPointPropertyType for location_position
left join route.chngovrpnttmslctp_lctnpstn_link route_ouksjl on route.changeoverpoint_t.hjid = route_ouksjl.changeoverpoint_t_hjid
left join gml.aixm_point_pt_view aixm_point_pt_view_iwfecu on route_ouksjl.locationposition_hjid = aixm_point_pt_view_iwfecu.hjid
-- composed RoutePortionPropertyType for applicable_route_portion
left join route.chngovrpnttmslctp_applcblrtprtn_link route_ilfhdy on route.changeoverpoint_t.hjid = route_ilfhdy.changeoverpoint_t_hjid
left join aixm.aixm_property aixm_property_unoacd on route_ilfhdy.applicablerouteportion_hjid = aixm_property_unoacd.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;;

