left join aixm.aixm_property aixm_property_dryyum on procedure_pjquit.holding_hjid = aixm_property_dryyum.hjid
-- composed StandardInstrumentDeparturePropertyType for departure
left join procedure.dprtrlgtmslctp_dprtr_link procedure_ngdstn on procedure.departureleg_t.hjid = procedure_ngdstn.departureleg_t_hjid
left join procedure.standardinstrumentdeparture_p standardinstrumentdeparture_bmzahn on procedure_ngdstn.departure_hjid = standardinstrumentdeparture_bmzahn.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;;

