    jsonb_build_object('href', angleindication_ymbhni.href,
    'nilreason', angleindication_ymbhni.nil_reason,
    'title', angleindication_ymbhni.simple_link_title) AS angle,
    -- composed DistanceIndicationPropertyType for distance,
    jsonb_build_object('href', distanceindication_jsmxzz.href,
    'nilreason', distanceindication_jsmxzz.nil_reason,
    'title', distanceindication_jsmxzz.simple_link_title) AS distance,
    -- composed HoldingUsePropertyType for holding,
    jsonb_build_object('hjid', aixm_property_kboogp.hjid,
    'nilreason', aixm_property_kboogp.nil_reason) AS holding,
    -- composed InstrumentApproachProcedurePropertyType for approach,
    jsonb_build_object('href', instrumentapproachprocedure_dkmfsn.href,
    'nilreason', instrumentapproachprocedure_dkmfsn.nil_reason,
    'title', instrumentapproachprocedure_dkmfsn.simple_link_title) AS approach,
    -- composed DesignatedPointPropertyType for final_path_alignment_point_fix_designated_point,
    jsonb_build_object('href', designatedpoint_qzodam.href,
    'nilreason', designatedpoint_qzodam.nil_reason,
    'title', designatedpoint_qzodam.simple_link_title) AS final_path_alignment_point_fix_designated_point,
    -- composed NavaidPropertyType for final_path_alignment_point_navaid_system,
    jsonb_build_object('href', navaid_dvhjnt.href,
    'nilreason', navaid_dvhjnt.nil_reason,
    'title', navaid_dvhjnt.simple_link_title) AS final_path_alignment_point_navaid_system,
    -- composed TouchDownLiftOffPropertyType for final_path_alignment_point_aiming_point,
    jsonb_build_object('href', touchdownliftoff_hywphr.href,
    'nilreason', touchdownliftoff_hywphr.nil_reason,
    'title', touchdownliftoff_hywphr.simple_link_title) AS final_path_alignment_point_aiming_point,
    -- composed RunwayCentrelinePointPropertyType for final_path_alignment_point_runway_point,
    jsonb_build_object('href', runwaycentrelinepoint_tvpqbr.href,
    'nilreason', runwaycentrelinepoint_tvpqbr.nil_reason,
    'title', runwaycentrelinepoint_tvpqbr.simple_link_title) AS final_path_alignment_point_runway_point,
    -- composed AirportHeliportPropertyType for final_path_alignment_point_airport_reference_point,
    jsonb_build_object('href', airportheliport_qzyfdy.href,
    'nilreason', airportheliport_qzyfdy.nil_reason,
    'title', airportheliport_qzyfdy.simple_link_title) AS final_path_alignment_point_airport_reference_point,
    -- composed TerminalSegmentPointPropertyType for visual_descent_point,
    jsonb_build_object('hjid', aixm_property_zvcmyz.hjid,
    'nilreason', aixm_property_zvcmyz.nil_reason) AS visual_descent_point,
    -- composed FASDataBlockPropertyType for fas_data,
    jsonb_build_object('hjid', aixm_property_llubwg.hjid,
    'nilreason', aixm_property_llubwg.nil_reason) AS fas_data,
    -- composed AircraftCharacteristicPropertyType for aircraft_category,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from procedure.fnllgtmslctp_arcrftctgr_link join aixm.aixm_property on procedure.fnllgtmslctp_arcrftctgr_link.aircraftcategory_hjid = aixm.aixm_property.hjid where procedure.finalleg_t.hjid = procedure.fnllgtmslctp_arcrftctgr_link.finalleg_t_hjid ) as aircraft_category,
    -- composed ObstacleAssessmentAreaPropertyType for design_surface,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from procedure.fnllgtmslctp_dsgnsrfc_link join aixm.aixm_property on procedure.fnllgtmslctp_dsgnsrfc_link.designsurface_hjid = aixm.aixm_property.hjid where procedure.finalleg_t.hjid = procedure.fnllgtmslctp_dsgnsrfc_link.finalleg_t_hjid ) as design_surface,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from procedure.fnllgtmslctp_annttn_link join aixm.aixm_property on procedure.fnllgtmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where procedure.finalleg_t.hjid = procedure.fnllgtmslctp_annttn_link.finalleg_t_hjid ) as annotation,
    -- composed ApproachConditionPropertyType for condition,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from procedure.fnllgtmslctp_cndtn_link join aixm.aixm_property on procedure.fnllgtmslctp_cndtn_link.condition_hjid = aixm.aixm_property.hjid where procedure.finalleg_t.hjid = procedure.fnllgtmslctp_cndtn_link.finalleg_t_hjid ) as condition
from aixm.aixm_feature
inner join procedure.finalleg_f on aixm.aixm_feature.hjid = procedure.finalleg_f.hjid
inner join procedure.finalleg_tp on aixm.aixm_feature.hjid = procedure.finalleg_tp.timeslice_hjid
inner join procedure.finalleg_t on procedure.finalleg_tp.finallegtimeslice_hjid = procedure.finalleg_t.hjid
inner join aixm.aixm_timeslice on procedure.finalleg_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed TerminalSegmentPointPropertyType for start_point
left join procedure.fnllgtmslctp_strtpnt_link procedure_jxyyuh on procedure.finalleg_t.hjid = procedure_jxyyuh.finalleg_t_hjid
left join aixm.aixm_property aixm_property_oweyzh on procedure_jxyyuh.startpoint_hjid = aixm_property_oweyzh.hjid
-- composed TerminalSegmentPointPropertyType for end_point
left join procedure.fnllgtmslctp_endpnt_link procedure_sadzom on procedure.finalleg_t.hjid = procedure_sadzom.finalleg_t_hjid
left join aixm.aixm_property aixm_property_mpmfbw on procedure_sadzom.endpoint_hjid = aixm_property_mpmfbw.hjid
-- composed AIXMCurvePropertyType for trajectory
left join procedure.fnllgtmslctp_trjctr_link procedure_rqhmep on procedure.finalleg_t.hjid = procedure_rqhmep.finalleg_t_hjid
left join gml.aixm_curve_pt_view aixm_curve_pt_view_upewbw on procedure_rqhmep.trajectory_hjid = aixm_curve_pt_view_upewbw.hjid
-- composed TerminalSegmentPointPropertyType for arc_centre
left join procedure.fnllgtmslctp_arccntr_link procedure_enpcdq on procedure.finalleg_t.hjid = procedure_enpcdq.finalleg_t_hjid
left join aixm.aixm_property aixm_property_ewzsye on procedure_enpcdq.arccentre_hjid = aixm_property_ewzsye.hjid
-- composed AngleIndicationPropertyType for angle
left join procedure.fnllgtmslctp_angl_link procedure_titptw on procedure.finalleg_t.hjid = procedure_titptw.finalleg_t_hjid
left join navaids_point.angleindication_p angleindication_ymbhni on procedure_titptw.angle_hjid = angleindication_ymbhni.hjid
-- composed DistanceIndicationPropertyType for distance
left join procedure.fnllgtmslctp_dstnc_link procedure_uzwwwm on procedure.finalleg_t.hjid = procedure_uzwwwm.finalleg_t_hjid
left join navaids_point.distanceindication_p distanceindication_jsmxzz on procedure_uzwwwm.distance_hjid = distanceindication_jsmxzz.hjid
-- composed HoldingUsePropertyType for holding
left join procedure.fnllgtmslctp_hldng_link procedure_tvbupg on procedure.finalleg_t.hjid = procedure_tvbupg.finalleg_t_hjid
left join aixm.aixm_property aixm_property_kboogp on procedure_tvbupg.holding_hjid = aixm_property_kboogp.hjid
-- composed InstrumentApproachProcedurePropertyType for approach
left join procedure.fnllgtmslctp_apprch_link procedure_mtxrpl on procedure.finalleg_t.hjid = procedure_mtxrpl.finalleg_t_hjid
left join procedure.instrumentapproachprocedure_p instrumentapproachprocedure_dkmfsn on procedure_mtxrpl.approach_hjid = instrumentapproachprocedure_dkmfsn.hjid
-- composed DesignatedPointPropertyType for final_path_alignment_point_fix_designated_point
left join procedure.fnllgtmslctp_fnlpthalgnmntpntfxdsgntdpnt_link procedure_uxguet on procedure.finalleg_t.hjid = procedure_uxguet.finalleg_t_hjid
left join navaids_point.designatedpoint_p designatedpoint_qzodam on procedure_uxguet.finalpathalignmentpointfixdesignatedpoint_hjid = designatedpoint_qzodam.hjid
-- composed NavaidPropertyType for final_path_alignment_point_navaid_system
left join procedure.fnllgtmslctp_fnlpthalgnmntpntnvdsstm_link procedure_fbkery on procedure.finalleg_t.hjid = procedure_fbkery.finalleg_t_hjid
left join navaids_point.navaid_p navaid_dvhjnt on procedure_fbkery.finalpathalignmentpointnavaidsystem_hjid = navaid_dvhjnt.hjid
-- composed TouchDownLiftOffPropertyType for final_path_alignment_point_aiming_point
left join procedure.fnllgtmslctp_fnlpthalgnmntpntamngpnt_link procedure_vuvoiw on procedure.finalleg_t.hjid = procedure_vuvoiw.finalleg_t_hjid
left join airport_heliport.touchdownliftoff_p touchdownliftoff_hywphr on procedure_vuvoiw.finalpathalignmentpointaimingpoint_hjid = touchdownliftoff_hywphr.hjid
-- composed RunwayCentrelinePointPropertyType for final_path_alignment_point_runway_point
left join procedure.fnllgtmslctp_fnlpthalgnmntpntrnwpnt_link procedure_zedczh on procedure.finalleg_t.hjid = procedure_zedczh.finalleg_t_hjid
left join airport_heliport.runwaycentrelinepoint_p runwaycentrelinepoint_tvpqbr on procedure_zedczh.finalpathalignmentpointrunwaypoint_hjid = runwaycentrelinepoint_tvpqbr.hjid
-- composed AirportHeliportPropertyType for final_path_alignment_point_airport_reference_point
left join procedure.fnllgtmslctp_fnlpthalgnmntpntarprtrfrncpnt_link procedure_mnyksz on procedure.finalleg_t.hjid = procedure_mnyksz.finalleg_t_hjid
left join airport_heliport.airportheliport_p airportheliport_qzyfdy on procedure_mnyksz.finalpathalignmentpointairportreferencepoint_hjid = airportheliport_qzyfdy.hjid
-- composed AIXMPointPropertyType for final_path_alignment_point_position
left join procedure.fnllgtmslctp_fnlpthalgnmntpntpstn_link procedure_nyluwk on procedure.finalleg_t.hjid = procedure_nyluwk.finalleg_t_hjid
left join gml.aixm_point_pt_view aixm_point_pt_view_zhedtf on procedure_nyluwk.finalpathalignmentpointposition_hjid = aixm_point_pt_view_zhedtf.hjid
-- composed TerminalSegmentPointPropertyType for visual_descent_point
left join procedure.fnllgtmslctp_vsldscntpnt_link procedure_gxmndp on procedure.finalleg_t.hjid = procedure_gxmndp.finalleg_t_hjid
left join aixm.aixm_property aixm_property_zvcmyz on procedure_gxmndp.visualdescentpoint_hjid = aixm_property_zvcmyz.hjid
-- composed FASDataBlockPropertyType for fas_data
left join procedure.fnllgtmslctp_fasdt_link procedure_sivppc on procedure.finalleg_t.hjid = procedure_sivppc.finalleg_t_hjid
left join aixm.aixm_property aixm_property_llubwg on procedure_sivppc.fasdata_hjid = aixm_property_llubwg.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;;

--service.firefightingservice_view

create or replace view service.firefightingservice_view as
select distinct on (aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number)
    uuid_generate_v5 ('6ba7b810-9dad-11d1-80b4-00c04fd430c8'::uuid, aixm.aixm_feature.hjid::text || '_' || aixm.aixm_timeslice.hjid::text) row,
    aixm.aixm_message.hjid as message_hjid,
    aixm.aixm_message.id as message_id,
    aixm.aixm_message.identifier as message_tidentifier,
    aixm.aixm_feature.hjid,
    aixm.aixm_feature.id as feature_id,
    aixm.aixm_feature.identifier,
    aixm.aixm_timeslice.id as timeslice_id,
    aixm.aixm_timeslice.hjid as timeslice_hjid,
    aixm.aixm_timeslice.interpretation,
    aixm.aixm_timeslice.sequence_number,
    aixm.aixm_timeslice.correction_number,
    aixm.aixm_timeslice.feature_lifetime_begin,
    aixm.aixm_timeslice.feature_lifetime_end,
    aixm.aixm_timeslice.valid_time_begin,
    COALESCE(aixm.aixm_timeslice.valid_time_end, '2100-01-01T00:00:00Z') AS valid_time_end,
    -- embedded CodeFlightDestinationType for getflightoperationsitem,
    service.firefightingservice_t.flightoperations::text,
    service.firefightingservice_t.flightoperationsnilreason::text,
    -- embedded CodeFacilityRankingType for getrankitem,
    service.firefightingservice_t.rank::text,
    service.firefightingservice_t.ranknilreason::text,
    -- embedded CodeYesNoType for getcomplianticaoitem,
    service.firefightingservice_t.complianticao::text,
    service.firefightingservice_t.complianticaonilreason::text,
    -- embedded TextNameType for getaixmnameitem,
    service.firefightingservice_t.name::text,
    service.firefightingservice_t.namenilreason::text,
    -- embedded CodeFireFightingType for getcategoryitem,
    service.firefightingservice_t.category::text,
    service.firefightingservice_t.categorynilreason::text,
    -- embedded CodeAviationStandardsType for getstandarditem,
    service.firefightingservice_t.standard::text,
    service.firefightingservice_t.standardnilreason::text,
    -- composed geometry AIXMElevatedPointPropertyType for location,
    aixm_elevated_point_pt_view_nzwwtr.geom as location_geom,
    jsonb_build_object('hjid', aixm_elevated_point_pt_view_nzwwtr.hjid,
    'id', aixm_elevated_point_pt_view_nzwwtr.id,
    'horizontalaccuracy', aixm_elevated_point_pt_view_nzwwtr.horizontalaccuracy,
    'horizontalaccuracy_uom', aixm_elevated_point_pt_view_nzwwtr.horizontalaccuracy_uom,
    'horizontalaccuracy_nilreason', aixm_elevated_point_pt_view_nzwwtr.horizontalaccuracy_nilreason,
    'geoidundulation', aixm_elevated_point_pt_view_nzwwtr.geoidundulation,
    'geoidundulation_uom', aixm_elevated_point_pt_view_nzwwtr.geoidundulation_uom,
    'geoidundulation_nilreason', aixm_elevated_point_pt_view_nzwwtr.geoidundulation_nilreason,
    'verticalaccuracy', aixm_elevated_point_pt_view_nzwwtr.verticalaccuracy,
    'verticalaccuracy_uom', aixm_elevated_point_pt_view_nzwwtr.verticalaccuracy_uom,
    'verticalaccuracy_nilreason', aixm_elevated_point_pt_view_nzwwtr.verticalaccuracy_nilreason,
    'elevation', aixm_elevated_point_pt_view_nzwwtr.elevation,
    'elevation_uom', aixm_elevated_point_pt_view_nzwwtr.elevation_uom,
    'elevation_nilreason', aixm_elevated_point_pt_view_nzwwtr.elevation_nilreason) AS location,
    -- composed UnitPropertyType for service_provider,
    jsonb_build_object('href', unit_phcjhq.href,
    'nilreason', unit_phcjhq.nil_reason,
    'title', unit_phcjhq.simple_link_title) AS service_provider,
    -- composed RadioCommunicationChannelPropertyType for radio_communication,
    (select coalesce(jsonb_agg(jsonb_build_object('href', service.radiocommunicationchannel_p.href,
    'nilreason', service.radiocommunicationchannel_p.nil_reason,
    'title', service.radiocommunicationchannel_p.simple_link_title)),'[]'::jsonb) from service.frfghtngsrvctmslctp_rdcmmnctn_link join service.radiocommunicationchannel_p on service.frfghtngsrvctmslctp_rdcmmnctn_link.radiocommunication_hjid = service.radiocommunicationchannel_p.hjid where service.firefightingservice_t.hjid = service.frfghtngsrvctmslctp_rdcmmnctn_link.firefightingservice_t_hjid ) as radio_communication,
    -- composed ContactInformationPropertyType for ground_communication,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from service.frfghtngsrvctmslctp_grndcmmnctn_link join aixm.aixm_property on service.frfghtngsrvctmslctp_grndcmmnctn_link.groundcommunication_hjid = aixm.aixm_property.hjid where service.firefightingservice_t.hjid = service.frfghtngsrvctmslctp_grndcmmnctn_link.firefightingservice_t_hjid ) as ground_communication,
    -- composed ServiceOperationalStatusPropertyType for availability,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from service.frfghtngsrvctmslctp_avlblt_link join aixm.aixm_property on service.frfghtngsrvctmslctp_avlblt_link.availability_hjid = aixm.aixm_property.hjid where service.firefightingservice_t.hjid = service.frfghtngsrvctmslctp_avlblt_link.firefightingservice_t_hjid ) as availability,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from service.frfghtngsrvctmslctp_annttn_link join aixm.aixm_property on service.frfghtngsrvctmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where service.firefightingservice_t.hjid = service.frfghtngsrvctmslctp_annttn_link.firefightingservice_t_hjid ) as annotation,
    -- composed AirportHeliportPropertyType for airport_heliport,
    (select coalesce(jsonb_agg(jsonb_build_object('href', airport_heliport.airportheliport_p.href,
    'nilreason', airport_heliport.airportheliport_p.nil_reason,
    'title', airport_heliport.airportheliport_p.simple_link_title)),'[]'::jsonb) from service.frfghtngsrvctmslctp_arprthlprt_link join airport_heliport.airportheliport_p on service.frfghtngsrvctmslctp_arprthlprt_link.airportheliport_hjid = airport_heliport.airportheliport_p.hjid where service.firefightingservice_t.hjid = service.frfghtngsrvctmslctp_arprthlprt_link.firefightingservice_t_hjid ) as airport_heliport
from aixm.aixm_feature
inner join service.firefightingservice_f on aixm.aixm_feature.hjid = service.firefightingservice_f.hjid
inner join service.firefightingservice_tp on aixm.aixm_feature.hjid = service.firefightingservice_tp.timeslice_hjid
inner join service.firefightingservice_t on service.firefightingservice_tp.firefightingservicetimeslice_hjid = service.firefightingservice_t.hjid
inner join aixm.aixm_timeslice on service.firefightingservice_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed AIXMElevatedPointPropertyType for location
left join service.frfghtngsrvctmslctp_lctn_link service_qqcard on service.firefightingservice_t.hjid = service_qqcard.firefightingservice_t_hjid
left join gml.aixm_elevated_point_pt_view aixm_elevated_point_pt_view_nzwwtr on service_qqcard.location_hjid = aixm_elevated_point_pt_view_nzwwtr.hjid
-- composed UnitPropertyType for service_provider
left join service.frfghtngsrvctmslctp_srvcprvdr_link service_fnjgyv on service.firefightingservice_t.hjid = service_fnjgyv.firefightingservice_t_hjid
left join organisation.unit_p unit_phcjhq on service_fnjgyv.serviceprovider_hjid = unit_phcjhq.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;;

--route.flightrestriction_view

create or replace view route.flightrestriction_view as
select distinct on (aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number)
    uuid_generate_v5 ('6ba7b810-9dad-11d1-80b4-00c04fd430c8'::uuid, aixm.aixm_feature.hjid::text || '_' || aixm.aixm_timeslice.hjid::text) row,
    aixm.aixm_message.hjid as message_hjid,
    aixm.aixm_message.id as message_id,
    aixm.aixm_message.identifier as message_tidentifier,
    aixm.aixm_feature.hjid,
    aixm.aixm_feature.id as feature_id,
    aixm.aixm_feature.identifier,
    aixm.aixm_timeslice.id as timeslice_id,
    aixm.aixm_timeslice.hjid as timeslice_hjid,
    aixm.aixm_timeslice.interpretation,
    aixm.aixm_timeslice.sequence_number,
    aixm.aixm_timeslice.correction_number,
    aixm.aixm_timeslice.feature_lifetime_begin,
    aixm.aixm_timeslice.feature_lifetime_end,
    aixm.aixm_timeslice.valid_time_begin,
    COALESCE(aixm.aixm_timeslice.valid_time_end, '2100-01-01T00:00:00Z') AS valid_time_end,
    -- embedded CodeFlightRestrictionDesignatorType for getdesignatoritem,
    route.flightrestriction_t.designator::text,
    route.flightrestriction_t.designatornilreason::text,
    -- embedded CodeFlightRestrictionType for gettypeitem,
    route.flightrestriction_t.type::text,
    route.flightrestriction_t.typenilreason::text,
    -- embedded TextInstructionType for getinstructionitem,
    route.flightrestriction_t.instruction::text,
    route.flightrestriction_t.instructionnilreason::text,
    -- composed FlightConditionCombinationPropertyType for flight,
    jsonb_build_object('hjid', aixm_property_tkidnr.hjid,
    'nilreason', aixm_property_tkidnr.nil_reason) AS flight,
    -- composed FlightRestrictionRoutePropertyType for regulated_route,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from route.flghtrstrctntmslctp_rgltdrt_link join aixm.aixm_property on route.flghtrstrctntmslctp_rgltdrt_link.regulatedroute_hjid = aixm.aixm_property.hjid where route.flightrestriction_t.hjid = route.flghtrstrctntmslctp_rgltdrt_link.flightrestriction_t_hjid ) as regulated_route,
