left join shared.hldngassssmnttmslctp_assssdhldngpttrn_link shared_yaclje on shared.holdingassessment_t.hjid = shared_yaclje.holdingassessment_t_hjid
left join holding.holdingpattern_p holdingpattern_ujmmzv on shared_yaclje.assessedholdingpattern_hjid = holdingpattern_ujmmzv.hjid
