left join service.infrmtnsrvctmslctp_srvcprvdr_link service_kazwhf on service.informationservice_t.hjid = service_kazwhf.informationservice_t_hjid
left join organisation.unit_p unit_ytcxvr on service_kazwhf.serviceprovider_hjid = unit_ytcxvr.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;;

