from aixm.aixm_feature
inner join procedure.initialleg_f on aixm.aixm_feature.hjid = procedure.initialleg_f.hjid
inner join procedure.initialleg_tp on aixm.aixm_feature.hjid = procedure.initialleg_tp.timeslice_hjid
inner join procedure.initialleg_t on procedure.initialleg_tp.initiallegtimeslice_hjid = procedure.initialleg_t.hjid
inner join aixm.aixm_timeslice on procedure.initialleg_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed TerminalSegmentPointPropertyType for start_point
left join procedure.intllgtmslctp_strtpnt_link procedure_icdwzj on procedure.initialleg_t.hjid = procedure_icdwzj.initialleg_t_hjid
left join aixm.aixm_property aixm_property_qvwbgq on procedure_icdwzj.startpoint_hjid = aixm_property_qvwbgq.hjid
-- composed TerminalSegmentPointPropertyType for end_point
left join procedure.intllgtmslctp_endpnt_link procedure_yjwxgh on procedure.initialleg_t.hjid = procedure_yjwxgh.initialleg_t_hjid
left join aixm.aixm_property aixm_property_aitebv on procedure_yjwxgh.endpoint_hjid = aixm_property_aitebv.hjid
-- composed AIXMCurvePropertyType for trajectory
left join procedure.intllgtmslctp_trjctr_link procedure_pkojfy on procedure.initialleg_t.hjid = procedure_pkojfy.initialleg_t_hjid
left join gml.aixm_curve_pt_view aixm_curve_pt_view_qlhdeq on procedure_pkojfy.trajectory_hjid = aixm_curve_pt_view_qlhdeq.hjid
-- composed TerminalSegmentPointPropertyType for arc_centre
left join procedure.intllgtmslctp_arccntr_link procedure_nnfqfn on procedure.initialleg_t.hjid = procedure_nnfqfn.initialleg_t_hjid
left join aixm.aixm_property aixm_property_heyxcx on procedure_nnfqfn.arccentre_hjid = aixm_property_heyxcx.hjid
-- composed AngleIndicationPropertyType for angle
left join procedure.intllgtmslctp_angl_link procedure_xudyio on procedure.initialleg_t.hjid = procedure_xudyio.initialleg_t_hjid
left join navaids_point.angleindication_p angleindication_fxgddb on procedure_xudyio.angle_hjid = angleindication_fxgddb.hjid
-- composed DistanceIndicationPropertyType for distance
left join procedure.intllgtmslctp_dstnc_link procedure_yiqket on procedure.initialleg_t.hjid = procedure_yiqket.initialleg_t_hjid
left join navaids_point.distanceindication_p distanceindication_prrgec on procedure_yiqket.distance_hjid = distanceindication_prrgec.hjid
-- composed HoldingUsePropertyType for holding
left join procedure.intllgtmslctp_hldng_link procedure_zqldsz on procedure.initialleg_t.hjid = procedure_zqldsz.initialleg_t_hjid
left join aixm.aixm_property aixm_property_txfpdr on procedure_zqldsz.holding_hjid = aixm_property_txfpdr.hjid
-- composed InstrumentApproachProcedurePropertyType for approach
left join procedure.intllgtmslctp_apprch_link procedure_oeafdy on procedure.initialleg_t.hjid = procedure_oeafdy.initialleg_t_hjid
left join procedure.instrumentapproachprocedure_p instrumentapproachprocedure_rmsmyy on procedure_oeafdy.approach_hjid = instrumentapproachprocedure_rmsmyy.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;;

