-- composed TerminalSegmentPointPropertyType for start_point
left join procedure.mssdapprchlgtmslctp_strtpnt_link procedure_hqwpbl on procedure.missedapproachleg_t.hjid = procedure_hqwpbl.missedapproachleg_t_hjid
left join aixm.aixm_property aixm_property_kvpzqu on procedure_hqwpbl.startpoint_hjid = aixm_property_kvpzqu.hjid
-- composed TerminalSegmentPointPropertyType for end_point
