    -- embedded TextNameType for getaixmnameitem,
    navaids_point.navaid_t.name::text,
    navaids_point.navaid_t.namenilreason::text,
    -- embedded CodeYesNoType for getflightcheckeditem,
    navaids_point.navaid_t.flightchecked::text,
    navaids_point.navaid_t.flightcheckednilreason::text,
    -- embedded CodeNavaidPurposeType for getpurposeitem,
    navaids_point.navaid_t.purpose::text,
    navaids_point.navaid_t.purposenilreason::text,
    -- embedded CodeSignalPerformanceILSType for getsignalperformanceitem,
    navaids_point.navaid_t.signalperformance::text,
    navaids_point.navaid_t.signalperformancenilreason::text,
    -- embedded CodeCourseQualityILSType for getcoursequalityitem,
    navaids_point.navaid_t.coursequality::text,
    navaids_point.navaid_t.coursequalitynilreason::text,
    -- embedded CodeIntegrityLevelILSType for getintegritylevelitem,
    navaids_point.navaid_t.integritylevel::text,
    navaids_point.navaid_t.integritylevelnilreason::text,
    -- composed geometry AIXMElevatedPointPropertyType for location,
    aixm_elevated_point_pt_view_zzrlrc.geom as location_geom,
    jsonb_build_object('hjid', aixm_elevated_point_pt_view_zzrlrc.hjid,
    'id', aixm_elevated_point_pt_view_zzrlrc.id,
    'horizontalaccuracy', aixm_elevated_point_pt_view_zzrlrc.horizontalaccuracy,
    'horizontalaccuracy_uom', aixm_elevated_point_pt_view_zzrlrc.horizontalaccuracy_uom,
    'horizontalaccuracy_nilreason', aixm_elevated_point_pt_view_zzrlrc.horizontalaccuracy_nilreason,
    'geoidundulation', aixm_elevated_point_pt_view_zzrlrc.geoidundulation,
    'geoidundulation_uom', aixm_elevated_point_pt_view_zzrlrc.geoidundulation_uom,
    'geoidundulation_nilreason', aixm_elevated_point_pt_view_zzrlrc.geoidundulation_nilreason,
    'verticalaccuracy', aixm_elevated_point_pt_view_zzrlrc.verticalaccuracy,
    'verticalaccuracy_uom', aixm_elevated_point_pt_view_zzrlrc.verticalaccuracy_uom,
    'verticalaccuracy_nilreason', aixm_elevated_point_pt_view_zzrlrc.verticalaccuracy_nilreason,
    'elevation', aixm_elevated_point_pt_view_zzrlrc.elevation,
