    'title', airport_heliport.airportheliport_p.simple_link_title)),'[]'::jsonb) from service.pssngrsrvctmslctp_arprthlprt_link join airport_heliport.airportheliport_p on service.pssngrsrvctmslctp_arprthlprt_link.airportheliport_hjid = airport_heliport.airportheliport_p.hjid where service.passengerservice_t.hjid = service.pssngrsrvctmslctp_arprthlprt_link.passengerservice_t_hjid ) as airport_heliport
from aixm.aixm_feature
inner join service.passengerservice_f on aixm.aixm_feature.hjid = service.passengerservice_f.hjid
inner join service.passengerservice_tp on aixm.aixm_feature.hjid = service.passengerservice_tp.timeslice_hjid
inner join service.passengerservice_t on service.passengerservice_tp.passengerservicetimeslice_hjid = service.passengerservice_t.hjid
inner join aixm.aixm_timeslice on service.passengerservice_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed AIXMElevatedPointPropertyType for location
left join service.pssngrsrvctmslctp_lctn_link service_ojajgu on service.passengerservice_t.hjid = service_ojajgu.passengerservice_t_hjid
left join gml.aixm_elevated_point_pt_view aixm_elevated_point_pt_view_lpuzax on service_ojajgu.location_hjid = aixm_elevated_point_pt_view_lpuzax.hjid
-- composed UnitPropertyType for service_provider
left join service.pssngrsrvctmslctp_srvcprvdr_link service_yrjolr on service.passengerservice_t.hjid = service_yrjolr.passengerservice_t_hjid
left join organisation.unit_p unit_itcwld on service_yrjolr.serviceprovider_hjid = unit_itcwld.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;;

