    service.radiocommunicationchannel_t.frequencyreception::text,
    service.radiocommunicationchannel_t.frequencyreceptionuom::text,
    service.radiocommunicationchannel_t.frequencyreceptionnilreason::text,
    -- composed geometry AIXMElevatedPointPropertyType for location,
    (select st_union(gml.aixm_elevated_point_pt_view.GEOM) as location_geom from service.rdcmmnctnchnnltmslctp_lctn_link join gml.aixm_elevated_point_pt_view on service.rdcmmnctnchnnltmslctp_lctn_link.location_hjid = gml.aixm_elevated_point_pt_view.hjid where service.radiocommunicationchannel_t.hjid = service.rdcmmnctnchnnltmslctp_lctn_link.radiocommunicationchannel_t_hjid ) as location_geom,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', gml.aixm_elevated_point_pt_view.hjid,
