    'verticalaccuracy_uom', gml.aixm_elevated_point_pt_view.verticalaccuracy_uom,
    'verticalaccuracy_nilreason', gml.aixm_elevated_point_pt_view.verticalaccuracy_nilreason,
    'elevation', gml.aixm_elevated_point_pt_view.elevation,
    'elevation_uom', gml.aixm_elevated_point_pt_view.elevation_uom,
    'elevation_nilreason', gml.aixm_elevated_point_pt_view.elevation_nilreason)),'[]'::jsonb) from service.rdcmmnctnchnnltmslctp_lctn_link join gml.aixm_elevated_point_pt_view on service.rdcmmnctnchnnltmslctp_lctn_link.location_hjid = gml.aixm_elevated_point_pt_view.hjid where service.radiocommunicationchannel_t.hjid = service.rdcmmnctnchnnltmslctp_lctn_link.radiocommunicationchannel_t_hjid ) as location,
    -- composed RadioCommunicationOperationalStatusPropertyType for availability,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from service.rdcmmnctnchnnltmslctp_avlblt_link join aixm.aixm_property on service.rdcmmnctnchnnltmslctp_avlblt_link.availability_hjid = aixm.aixm_property.hjid where service.radiocommunicationchannel_t.hjid = service.rdcmmnctnchnnltmslctp_avlblt_link.radiocommunicationchannel_t_hjid ) as availability,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from service.rdcmmnctnchnnltmslctp_annttn_link join aixm.aixm_property on service.rdcmmnctnchnnltmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where service.radiocommunicationchannel_t.hjid = service.rdcmmnctnchnnltmslctp_annttn_link.radiocommunicationchannel_t_hjid ) as annotation
from aixm.aixm_feature
inner join service.radiocommunicationchannel_f on aixm.aixm_feature.hjid = service.radiocommunicationchannel_f.hjid
inner join service.radiocommunicationchannel_tp on aixm.aixm_feature.hjid = service.radiocommunicationchannel_tp.timeslice_hjid
inner join service.radiocommunicationchannel_t on service.radiocommunicationchannel_tp.radiocommunicationchanneltimeslice_hjid = service.radiocommunicationchannel_t.hjid
inner join aixm.aixm_timeslice on service.radiocommunicationchannel_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
