--shared.radiofrequencyarea_view

create or replace view shared.radiofrequencyarea_view as
select distinct on (aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number)
    uuid_generate_v5 ('6ba7b810-9dad-11d1-80b4-00c04fd430c8'::uuid, aixm.aixm_feature.hjid::text || '_' || aixm.aixm_timeslice.hjid::text) row,
    aixm.aixm_message.hjid as message_hjid,
    aixm.aixm_message.id as message_id,
    aixm.aixm_message.identifier as message_tidentifier,
    aixm.aixm_feature.hjid,
    aixm.aixm_feature.id as feature_id,
    aixm.aixm_feature.identifier,
    aixm.aixm_timeslice.id as timeslice_id,
    aixm.aixm_timeslice.hjid as timeslice_hjid,
    aixm.aixm_timeslice.interpretation,
    aixm.aixm_timeslice.sequence_number,
    aixm.aixm_timeslice.correction_number,
    aixm.aixm_timeslice.feature_lifetime_begin,
    aixm.aixm_timeslice.feature_lifetime_end,
    aixm.aixm_timeslice.valid_time_begin,
    COALESCE(aixm.aixm_timeslice.valid_time_end, '2100-01-01T00:00:00Z') AS valid_time_end,
    -- embedded CodeRadioFrequencyAreaType for gettypeitem,
    shared.radiofrequencyarea_t.type::text,
    shared.radiofrequencyarea_t.typenilreason::text,
    -- embedded ValAngleType for getanglescallopitem,
    shared.radiofrequencyarea_t.anglescallop::text,
    shared.radiofrequencyarea_t.anglescallopnilreason::text,
    -- embedded CodeRadioSignalType for getsignaltypeitem,
    shared.radiofrequencyarea_t.signaltype::text,
    shared.radiofrequencyarea_t.signaltypenilreason::text,
    -- composed NavaidEquipmentPropertyType for equipment_navaid_equipment,
    jsonb_build_object('hjid', aixm_property_ajrnwl.hjid,
    'nilreason', aixm_property_ajrnwl.nil_reason) AS equipment_navaid_equipment,
    -- composed RadioCommunicationChannelPropertyType for equipment_frequency,
    jsonb_build_object('href', radiocommunicationchannel_mrwtop.href,
    'nilreason', radiocommunicationchannel_mrwtop.nil_reason,
    'title', radiocommunicationchannel_mrwtop.simple_link_title) AS equipment_frequency,
    -- composed SpecialNavigationStationPropertyType for equipment_special_navigation_station,
    jsonb_build_object('href', specialnavigationstation_sjpvls.href,
    'nilreason', specialnavigationstation_sjpvls.nil_reason,
    'title', specialnavigationstation_sjpvls.simple_link_title) AS equipment_special_navigation_station,
    -- composed PrecisionApproachRadarPropertyType for equipment_precision_approach_radar,
    jsonb_build_object('href', precisionapproachradar_souick.href,
    'nilreason', precisionapproachradar_souick.nil_reason,
    'title', precisionapproachradar_souick.simple_link_title) AS equipment_precision_approach_radar,
    -- composed SecondarySurveillanceRadarPropertyType for equipment_radar,
    jsonb_build_object('href', secondarysurveillanceradar_nonifq.href,
    'nilreason', secondarysurveillanceradar_nonifq.nil_reason,
    'title', secondarysurveillanceradar_nonifq.simple_link_title) AS equipment_radar,
    -- composed CircleSectorPropertyType for sector,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from shared.rdfrqncartmslctp_sctr_link join aixm.aixm_property on shared.rdfrqncartmslctp_sctr_link.sector_hjid = aixm.aixm_property.hjid where shared.radiofrequencyarea_t.hjid = shared.rdfrqncartmslctp_sctr_link.radiofrequencyarea_t_hjid ) as sector,
    -- composed geometry AIXMSurfacePropertyType for extent,
    (select st_union(gml.aixm_surface_pt_view.GEOM) as extent_geom from shared.rdfrqncartmslctp_extnt_link join gml.aixm_surface_pt_view on shared.rdfrqncartmslctp_extnt_link.extent_hjid = gml.aixm_surface_pt_view.hjid where shared.radiofrequencyarea_t.hjid = shared.rdfrqncartmslctp_extnt_link.radiofrequencyarea_t_hjid ) as extent_geom,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', gml.aixm_surface_pt_view.hjid,
    'id', gml.aixm_surface_pt_view.id,
    'horizontalaccuracy', gml.aixm_surface_pt_view.horizontalaccuracy,
    'horizontalaccuracy_uom', gml.aixm_surface_pt_view.horizontalaccuracy_uom,
    'horizontalaccuracy_nilreason', gml.aixm_surface_pt_view.horizontalaccuracy_nilreason)),'[]'::jsonb) from shared.rdfrqncartmslctp_extnt_link join gml.aixm_surface_pt_view on shared.rdfrqncartmslctp_extnt_link.extent_hjid = gml.aixm_surface_pt_view.hjid where shared.radiofrequencyarea_t.hjid = shared.rdfrqncartmslctp_extnt_link.radiofrequencyarea_t_hjid ) as extent,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from shared.rdfrqncartmslctp_annttn_link join aixm.aixm_property on shared.rdfrqncartmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where shared.radiofrequencyarea_t.hjid = shared.rdfrqncartmslctp_annttn_link.radiofrequencyarea_t_hjid ) as annotation
from aixm.aixm_feature
inner join shared.radiofrequencyarea_f on aixm.aixm_feature.hjid = shared.radiofrequencyarea_f.hjid
inner join shared.radiofrequencyarea_tp on aixm.aixm_feature.hjid = shared.radiofrequencyarea_tp.timeslice_hjid
inner join shared.radiofrequencyarea_t on shared.radiofrequencyarea_tp.radiofrequencyareatimeslice_hjid = shared.radiofrequencyarea_t.hjid
inner join aixm.aixm_timeslice on shared.radiofrequencyarea_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed NavaidEquipmentPropertyType for equipment_navaid_equipment
left join shared.rdfrqncartmslctp_eqpmntnvdeqpmnt_link shared_tnluga on shared.radiofrequencyarea_t.hjid = shared_tnluga.radiofrequencyarea_t_hjid
left join aixm.aixm_property aixm_property_ajrnwl on shared_tnluga.equipmentnavaidequipment_hjid = aixm_property_ajrnwl.hjid
-- composed RadioCommunicationChannelPropertyType for equipment_frequency
left join shared.rdfrqncartmslctp_eqpmntfrqnc_link shared_aphhrn on shared.radiofrequencyarea_t.hjid = shared_aphhrn.radiofrequencyarea_t_hjid
left join service.radiocommunicationchannel_p radiocommunicationchannel_mrwtop on shared_aphhrn.equipmentfrequency_hjid = radiocommunicationchannel_mrwtop.hjid
-- composed SpecialNavigationStationPropertyType for equipment_special_navigation_station
left join shared.rdfrqncartmslctp_eqpmntspclnvgtnsttn_link shared_tavizd on shared.radiofrequencyarea_t.hjid = shared_tavizd.radiofrequencyarea_t_hjid
left join navaids_point.specialnavigationstation_p specialnavigationstation_sjpvls on shared_tavizd.equipmentspecialnavigationstation_hjid = specialnavigationstation_sjpvls.hjid
-- composed PrecisionApproachRadarPropertyType for equipment_precision_approach_radar
left join shared.rdfrqncartmslctp_eqpmntprcsnapprchrdr_link shared_tkxpqn on shared.radiofrequencyarea_t.hjid = shared_tkxpqn.radiofrequencyarea_t_hjid
left join surveillance.precisionapproachradar_p precisionapproachradar_souick on shared_tkxpqn.equipmentprecisionapproachradar_hjid = precisionapproachradar_souick.hjid
-- composed SecondarySurveillanceRadarPropertyType for equipment_radar
left join shared.rdfrqncartmslctp_eqpmntrdr_link shared_bkhooa on shared.radiofrequencyarea_t.hjid = shared_bkhooa.radiofrequencyarea_t_hjid
left join surveillance.secondarysurveillanceradar_p secondarysurveillanceradar_nonifq on shared_bkhooa.equipmentradar_hjid = secondarysurveillanceradar_nonifq.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;;

