    route.routedme_t.criticaldmenilreason::text,
    -- embedded CodeYesNoType for getsatisfactoryitem,
    route.routedme_t.satisfactory::text,
    route.routedme_t.satisfactorynilreason::text,
    -- composed DMEPropertyType for referenced_dme,
    jsonb_build_object('href', dme_blcrpg.href,
    'nilreason', dme_blcrpg.nil_reason,
    'title', dme_blcrpg.simple_link_title) AS referenced_dme,
    -- composed RoutePortionPropertyType for applicable_route_portion,
    jsonb_build_object('hjid', aixm_property_txqazx.hjid,
    'nilreason', aixm_property_txqazx.nil_reason) AS applicable_route_portion,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from route.rtdmetmslctp_annttn_link join aixm.aixm_property on route.rtdmetmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where route.routedme_t.hjid = route.rtdmetmslctp_annttn_link.routedme_t_hjid ) as annotation
from aixm.aixm_feature
inner join route.routedme_f on aixm.aixm_feature.hjid = route.routedme_f.hjid
inner join route.routedme_tp on aixm.aixm_feature.hjid = route.routedme_tp.timeslice_hjid
inner join route.routedme_t on route.routedme_tp.routedmetimeslice_hjid = route.routedme_t.hjid
inner join aixm.aixm_timeslice on route.routedme_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed DMEPropertyType for referenced_dme
left join route.rtdmetmslctp_rfrncddme_link route_zjfcsd on route.routedme_t.hjid = route_zjfcsd.routedme_t_hjid
left join navaids_point.dme_p dme_blcrpg on route_zjfcsd.referenceddme_hjid = dme_blcrpg.hjid
-- composed RoutePortionPropertyType for applicable_route_portion
left join route.rtdmetmslctp_applcblrtprtn_link route_gtwzpc on route.routedme_t.hjid = route_gtwzpc.routedme_t_hjid
left join aixm.aixm_property aixm_property_txqazx on route_gtwzpc.applicablerouteportion_hjid = aixm_property_txqazx.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;;

