    uuid_generate_v5 ('6ba7b810-9dad-11d1-80b4-00c04fd430c8'::uuid, aixm.aixm_feature.hjid::text || '_' || aixm.aixm_timeslice.hjid::text) row,
    aixm.aixm_message.hjid as message_hjid,
    aixm.aixm_message.id as message_id,
    aixm.aixm_message.identifier as message_tidentifier,
    aixm.aixm_feature.hjid,
    aixm.aixm_feature.id as feature_id,
    aixm.aixm_feature.identifier,
    aixm.aixm_timeslice.id as timeslice_id,
    aixm.aixm_timeslice.hjid as timeslice_hjid,
    aixm.aixm_timeslice.interpretation,
    aixm.aixm_timeslice.sequence_number,
    aixm.aixm_timeslice.correction_number,
    aixm.aixm_timeslice.feature_lifetime_begin,
    aixm.aixm_timeslice.feature_lifetime_end,
    aixm.aixm_timeslice.valid_time_begin,
    COALESCE(aixm.aixm_timeslice.valid_time_end, '2100-01-01T00:00:00Z') AS valid_time_end,
    -- embedded CodeStatusOperationsType for getstatusitem,
    airport_heliport.runwayblastpad_t.status::text,
    airport_heliport.runwayblastpad_t.statusnilreason::text,
    -- embedded ValDistanceType for getlengthitem,
    airport_heliport.runwayblastpad_t.length::text,
    airport_heliport.runwayblastpad_t.lengthuom::text,
    airport_heliport.runwayblastpad_t.lengthnilreason::text,
    -- composed geometry AIXMElevatedSurfacePropertyType for extent,
    aixm_elevated_surface_pt_view_rzmids.geom as extent_geom,
    jsonb_build_object('hjid', aixm_elevated_surface_pt_view_rzmids.hjid,
    'id', aixm_elevated_surface_pt_view_rzmids.id,
    'horizontalaccuracy', aixm_elevated_surface_pt_view_rzmids.horizontalaccuracy,
    'horizontalaccuracy_uom', aixm_elevated_surface_pt_view_rzmids.horizontalaccuracy_uom,
    'horizontalaccuracy_nilreason', aixm_elevated_surface_pt_view_rzmids.horizontalaccuracy_nilreason,
    'geoidundulation', aixm_elevated_surface_pt_view_rzmids.geoidundulation,
    'geoidundulation_uom', aixm_elevated_surface_pt_view_rzmids.geoidundulation_uom,
    'geoidundulation_nilreason', aixm_elevated_surface_pt_view_rzmids.geoidundulation_nilreason,
    'verticalaccuracy', aixm_elevated_surface_pt_view_rzmids.verticalaccuracy,
    'verticalaccuracy_uom', aixm_elevated_surface_pt_view_rzmids.verticalaccuracy_uom,
    'verticalaccuracy_nilreason', aixm_elevated_surface_pt_view_rzmids.verticalaccuracy_nilreason,
    'elevation', aixm_elevated_surface_pt_view_rzmids.elevation,
    'elevation_uom', aixm_elevated_surface_pt_view_rzmids.elevation_uom,
    'elevation_nilreason', aixm_elevated_surface_pt_view_rzmids.elevation_nilreason) AS extent,
    -- composed RunwayDirectionPropertyType for used_runway_direction,
    jsonb_build_object('href', runwaydirection_elarhi.href,
    'nilreason', runwaydirection_elarhi.nil_reason,
    'title', runwaydirection_elarhi.simple_link_title) AS used_runway_direction,
    -- composed SurfaceCharacteristicsPropertyType for surface_properties,
    jsonb_build_object('hjid', aixm_property_edkaqs.hjid,
    'nilreason', aixm_property_edkaqs.nil_reason) AS surface_properties,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from airport_heliport.rnwblstpdtmslctp_annttn_link join aixm.aixm_property on airport_heliport.rnwblstpdtmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where airport_heliport.runwayblastpad_t.hjid = airport_heliport.rnwblstpdtmslctp_annttn_link.runwayblastpad_t_hjid ) as annotation
from aixm.aixm_feature
inner join airport_heliport.runwayblastpad_f on aixm.aixm_feature.hjid = airport_heliport.runwayblastpad_f.hjid
inner join airport_heliport.runwayblastpad_tp on aixm.aixm_feature.hjid = airport_heliport.runwayblastpad_tp.timeslice_hjid
inner join airport_heliport.runwayblastpad_t on airport_heliport.runwayblastpad_tp.runwayblastpadtimeslice_hjid = airport_heliport.runwayblastpad_t.hjid
inner join aixm.aixm_timeslice on airport_heliport.runwayblastpad_t.hjid = aixm.aixm_timeslice.hjid
