inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed RunwayDirectionPropertyType for used_runway_direction
left join airport_heliport.rnwblstpdtmslctp_usdrnwdrctn_link airport_heliport_hxjxbw on airport_heliport.runwayblastpad_t.hjid = airport_heliport_hxjxbw.runwayblastpad_t_hjid
left join airport_heliport.runwaydirection_p runwaydirection_elarhi on airport_heliport_hxjxbw.usedrunwaydirection_hjid = runwaydirection_elarhi.hjid
-- composed AIXMElevatedSurfacePropertyType for extent
left join airport_heliport.rnwblstpdtmslctp_extnt_link airport_heliport_fwgtfm on airport_heliport.runwayblastpad_t.hjid = airport_heliport_fwgtfm.runwayblastpad_t_hjid
left join gml.aixm_elevated_surface_pt_view aixm_elevated_surface_pt_view_rzmids on airport_heliport_fwgtfm.extent_hjid = aixm_elevated_surface_pt_view_rzmids.hjid
-- composed SurfaceCharacteristicsPropertyType for surface_properties
left join airport_heliport.rnwblstpdtmslctp_srfcprprts_link airport_heliport_qrlrix on airport_heliport.runwayblastpad_t.hjid = airport_heliport_qrlrix.runwayblastpad_t_hjid
left join aixm.aixm_property aixm_property_edkaqs on airport_heliport_qrlrix.surfaceproperties_hjid = aixm_property_edkaqs.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;;

