    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from navaids_point.sdftmslctp_annttn_link join aixm.aixm_property on navaids_point.sdftmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where navaids_point.sdf_t.hjid = navaids_point.sdftmslctp_annttn_link.sdf_t_hjid ) as annotation
