    uuid_generate_v5 ('6ba7b810-9dad-11d1-80b4-00c04fd430c8'::uuid, aixm.aixm_feature.hjid::text || '_' || aixm.aixm_timeslice.hjid::text) row,
    aixm.aixm_message.hjid as message_hjid,
    aixm.aixm_message.id as message_id,
    aixm.aixm_message.identifier as message_tidentifier,
    aixm.aixm_feature.hjid,
    aixm.aixm_feature.id as feature_id,
    aixm.aixm_feature.identifier,
    aixm.aixm_timeslice.id as timeslice_id,
    aixm.aixm_timeslice.hjid as timeslice_hjid,
    aixm.aixm_timeslice.interpretation,
    aixm.aixm_timeslice.sequence_number,
    aixm.aixm_timeslice.correction_number,
    aixm.aixm_timeslice.feature_lifetime_begin,
    aixm.aixm_timeslice.feature_lifetime_end,
    aixm.aixm_timeslice.valid_time_begin,
    COALESCE(aixm.aixm_timeslice.valid_time_end, '2100-01-01T00:00:00Z') AS valid_time_end,
    -- embedded CodeSpecialNavigationSystemType for gettypeitem,
    navaids_point.specialnavigationsystem_t.type::text,
    navaids_point.specialnavigationsystem_t.typenilreason::text,
    -- embedded CodeSpecialNavigationChainDesignatorType for getdesignatoritem,
    navaids_point.specialnavigationsystem_t.designator::text,
    navaids_point.specialnavigationsystem_t.designatornilreason::text,
    -- embedded TextNameType for getaixmnameitem,
    navaids_point.specialnavigationsystem_t.name::text,
    navaids_point.specialnavigationsystem_t.namenilreason::text,
    -- composed AuthorityForSpecialNavigationSystemPropertyType for responsible_organisation,
    jsonb_build_object('hjid', aixm_property_evavub.hjid,
    'nilreason', aixm_property_evavub.nil_reason) AS responsible_organisation,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from navaids_point.spclnvgtnsstmtmslctp_annttn_link join aixm.aixm_property on navaids_point.spclnvgtnsstmtmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where navaids_point.specialnavigationsystem_t.hjid = navaids_point.spclnvgtnsstmtmslctp_annttn_link.specialnavigationsystem_t_hjid ) as annotation
from aixm.aixm_feature
inner join navaids_point.specialnavigationsystem_f on aixm.aixm_feature.hjid = navaids_point.specialnavigationsystem_f.hjid
inner join navaids_point.specialnavigationsystem_tp on aixm.aixm_feature.hjid = navaids_point.specialnavigationsystem_tp.timeslice_hjid
inner join navaids_point.specialnavigationsystem_t on navaids_point.specialnavigationsystem_tp.specialnavigationsystemtimeslice_hjid = navaids_point.specialnavigationsystem_t.hjid
inner join aixm.aixm_timeslice on navaids_point.specialnavigationsystem_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed AuthorityForSpecialNavigationSystemPropertyType for responsible_organisation
left join navaids_point.spclnvgtnsstmtmslctp_rspnsblorgnstn_link navaids_point_iyfovq on navaids_point.specialnavigationsystem_t.hjid = navaids_point_iyfovq.specialnavigationsystem_t_hjid
left join aixm.aixm_property aixm_property_evavub on navaids_point_iyfovq.responsibleorganisation_hjid = aixm_property_evavub.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;;

