    uuid_generate_v5 ('6ba7b810-9dad-11d1-80b4-00c04fd430c8'::uuid, aixm.aixm_feature.hjid::text || '_' || aixm.aixm_timeslice.hjid::text) row,
    aixm.aixm_message.hjid as message_hjid,
    aixm.aixm_message.id as message_id,
    aixm.aixm_message.identifier as message_tidentifier,
    aixm.aixm_feature.hjid,
    aixm.aixm_feature.id as feature_id,
    aixm.aixm_feature.identifier,
    aixm.aixm_timeslice.id as timeslice_id,
    aixm.aixm_timeslice.hjid as timeslice_hjid,
    aixm.aixm_timeslice.interpretation,
    aixm.aixm_timeslice.sequence_number,
    aixm.aixm_timeslice.correction_number,
    aixm.aixm_timeslice.feature_lifetime_begin,
    aixm.aixm_timeslice.feature_lifetime_end,
    aixm.aixm_timeslice.valid_time_begin,
    COALESCE(aixm.aixm_timeslice.valid_time_end, '2100-01-01T00:00:00Z') AS valid_time_end,
    -- embedded TextDesignatorType for getdesignatoritem,
    airport_heliport.taxiway_t.designator::text,
    airport_heliport.taxiway_t.designatornilreason::text,
    -- embedded CodeTaxiwayType for gettypeitem,
    airport_heliport.taxiway_t.type::text,
    airport_heliport.taxiway_t.typenilreason::text,
    -- embedded CodeYesNoType for getabandoneditem,
    airport_heliport.taxiway_t.abandoned::text,
    airport_heliport.taxiway_t.abandonednilreason::text,
    -- embedded ValDistanceType for getwidthitem,
    airport_heliport.taxiway_t.width::text,
    airport_heliport.taxiway_t.widthuom::text,
    airport_heliport.taxiway_t.widthnilreason::text,
    -- embedded ValDistanceType for getwidthshoulderitem,
    airport_heliport.taxiway_t.widthshoulder::text,
    airport_heliport.taxiway_t.widthshoulderuom::text,
    airport_heliport.taxiway_t.widthshouldernilreason::text,
    -- embedded ValDistanceType for getlengthitem,
    airport_heliport.taxiway_t.length::text,
    airport_heliport.taxiway_t.lengthuom::text,
    airport_heliport.taxiway_t.lengthnilreason::text,
    -- composed SurfaceCharacteristicsPropertyType for surface_properties,
    jsonb_build_object('hjid', aixm_property_ldtdch.hjid,
    'nilreason', aixm_property_ldtdch.nil_reason) AS surface_properties,
    -- composed AirportHeliportPropertyType for associated_airport_heliport,
    jsonb_build_object('href', airportheliport_aqygjx.href,
    'nilreason', airportheliport_aqygjx.nil_reason,
    'title', airportheliport_aqygjx.simple_link_title) AS associated_airport_heliport,
    -- composed TaxiwayContaminationPropertyType for contaminant,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from airport_heliport.txwtmslctp_cntmnnt_link join aixm.aixm_property on airport_heliport.txwtmslctp_cntmnnt_link.contaminant_hjid = aixm.aixm_property.hjid where airport_heliport.taxiway_t.hjid = airport_heliport.txwtmslctp_cntmnnt_link.taxiway_t_hjid ) as contaminant,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from airport_heliport.txwtmslctp_annttn_link join aixm.aixm_property on airport_heliport.txwtmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where airport_heliport.taxiway_t.hjid = airport_heliport.txwtmslctp_annttn_link.taxiway_t_hjid ) as annotation,
    -- composed ManoeuvringAreaAvailabilityPropertyType for availability,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from airport_heliport.txwtmslctp_avlblt_link join aixm.aixm_property on airport_heliport.txwtmslctp_avlblt_link.availability_hjid = aixm.aixm_property.hjid where airport_heliport.taxiway_t.hjid = airport_heliport.txwtmslctp_avlblt_link.taxiway_t_hjid ) as availability
from aixm.aixm_feature
inner join airport_heliport.taxiway_f on aixm.aixm_feature.hjid = airport_heliport.taxiway_f.hjid
inner join airport_heliport.taxiway_tp on aixm.aixm_feature.hjid = airport_heliport.taxiway_tp.timeslice_hjid
inner join airport_heliport.taxiway_t on airport_heliport.taxiway_tp.taxiwaytimeslice_hjid = airport_heliport.taxiway_t.hjid
inner join aixm.aixm_timeslice on airport_heliport.taxiway_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed SurfaceCharacteristicsPropertyType for surface_properties
left join airport_heliport.txwtmslctp_srfcprprts_link airport_heliport_jctwiv on airport_heliport.taxiway_t.hjid = airport_heliport_jctwiv.taxiway_t_hjid
left join aixm.aixm_property aixm_property_ldtdch on airport_heliport_jctwiv.surfaceproperties_hjid = aixm_property_ldtdch.hjid
-- composed AirportHeliportPropertyType for associated_airport_heliport
left join airport_heliport.txwtmslctp_assctdarprthlprt_link airport_heliport_rhobta on airport_heliport.taxiway_t.hjid = airport_heliport_rhobta.taxiway_t_hjid
left join airport_heliport.airportheliport_p airportheliport_aqygjx on airport_heliport_rhobta.associatedairportheliport_hjid = airportheliport_aqygjx.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;;

--procedure.terminalarrivalarea_view

create or replace view procedure.terminalarrivalarea_view as
select distinct on (aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number)
    uuid_generate_v5 ('6ba7b810-9dad-11d1-80b4-00c04fd430c8'::uuid, aixm.aixm_feature.hjid::text || '_' || aixm.aixm_timeslice.hjid::text) row,
    aixm.aixm_message.hjid as message_hjid,
    aixm.aixm_message.id as message_id,
    aixm.aixm_message.identifier as message_tidentifier,
    aixm.aixm_feature.hjid,
    aixm.aixm_feature.id as feature_id,
    aixm.aixm_feature.identifier,
    aixm.aixm_timeslice.id as timeslice_id,
    aixm.aixm_timeslice.hjid as timeslice_hjid,
    aixm.aixm_timeslice.interpretation,
    aixm.aixm_timeslice.sequence_number,
    aixm.aixm_timeslice.correction_number,
    aixm.aixm_timeslice.feature_lifetime_begin,
    aixm.aixm_timeslice.feature_lifetime_end,
    aixm.aixm_timeslice.valid_time_begin,
    COALESCE(aixm.aixm_timeslice.valid_time_end, '2100-01-01T00:00:00Z') AS valid_time_end,
    -- embedded CodeTAAType for getarrivalareatypeitem,
    procedure.terminalarrivalarea_t.arrivalareatype::text,
    procedure.terminalarrivalarea_t.arrivalareatypenilreason::text,
    -- embedded ValDistanceType for getouterbufferwidthitem,
    procedure.terminalarrivalarea_t.outerbufferwidth::text,
    procedure.terminalarrivalarea_t.outerbufferwidthuom::text,
    procedure.terminalarrivalarea_t.outerbufferwidthnilreason::text,
    -- embedded ValDistanceType for getlateralbufferwidthitem,
    procedure.terminalarrivalarea_t.lateralbufferwidth::text,
    procedure.terminalarrivalarea_t.lateralbufferwidthuom::text,
    procedure.terminalarrivalarea_t.lateralbufferwidthnilreason::text,
    -- composed geometry AIXMPointPropertyType for if_position,
    aixm_point_pt_view_hvfavo.geom as if_position_geom,
    jsonb_build_object('hjid', aixm_point_pt_view_hvfavo.hjid,
    'id', aixm_point_pt_view_hvfavo.id,
    'horizontalaccuracy', aixm_point_pt_view_hvfavo.horizontalaccuracy,
    'horizontalaccuracy_uom', aixm_point_pt_view_hvfavo.horizontalaccuracy_uom,
    'horizontalaccuracy_nilreason', aixm_point_pt_view_hvfavo.horizontalaccuracy_nilreason) AS if_position,
    -- composed geometry AIXMPointPropertyType for iaf_position,
    aixm_point_pt_view_nqthuv.geom as iaf_position_geom,
    jsonb_build_object('hjid', aixm_point_pt_view_nqthuv.hjid,
    'id', aixm_point_pt_view_nqthuv.id,
    'horizontalaccuracy', aixm_point_pt_view_nqthuv.horizontalaccuracy,
    'horizontalaccuracy_uom', aixm_point_pt_view_nqthuv.horizontalaccuracy_uom,
    'horizontalaccuracy_nilreason', aixm_point_pt_view_nqthuv.horizontalaccuracy_nilreason) AS iaf_position,
    -- composed geometry AIXMSurfacePropertyType for buffer,
    aixm_surface_pt_view_wsbkjn.geom as buffer_geom,
    jsonb_build_object('hjid', aixm_surface_pt_view_wsbkjn.hjid,
    'id', aixm_surface_pt_view_wsbkjn.id,
    'horizontalaccuracy', aixm_surface_pt_view_wsbkjn.horizontalaccuracy,
    'horizontalaccuracy_uom', aixm_surface_pt_view_wsbkjn.horizontalaccuracy_uom,
    'horizontalaccuracy_nilreason', aixm_surface_pt_view_wsbkjn.horizontalaccuracy_nilreason) AS buffer,
    -- composed DesignatedPointPropertyType for if_fix_designated_point,
    jsonb_build_object('href', designatedpoint_lujols.href,
    'nilreason', designatedpoint_lujols.nil_reason,
    'title', designatedpoint_lujols.simple_link_title) AS if_fix_designated_point,
    -- composed NavaidPropertyType for if_navaid_system,
    jsonb_build_object('href', navaid_mrbdps.href,
    'nilreason', navaid_mrbdps.nil_reason,
    'title', navaid_mrbdps.simple_link_title) AS if_navaid_system,
    -- composed TouchDownLiftOffPropertyType for if_aiming_point,
    jsonb_build_object('href', touchdownliftoff_wsnmox.href,
    'nilreason', touchdownliftoff_wsnmox.nil_reason,
    'title', touchdownliftoff_wsnmox.simple_link_title) AS if_aiming_point,
    -- composed RunwayCentrelinePointPropertyType for if_runway_point,
    jsonb_build_object('href', runwaycentrelinepoint_zlbgtd.href,
    'nilreason', runwaycentrelinepoint_zlbgtd.nil_reason,
    'title', runwaycentrelinepoint_zlbgtd.simple_link_title) AS if_runway_point,
    -- composed AirportHeliportPropertyType for if_airport_reference_point,
    jsonb_build_object('href', airportheliport_qjefwr.href,
    'nilreason', airportheliport_qjefwr.nil_reason,
    'title', airportheliport_qjefwr.simple_link_title) AS if_airport_reference_point,
    -- composed DesignatedPointPropertyType for iaf_fix_designated_point,
    jsonb_build_object('href', designatedpoint_wlzccb.href,
    'nilreason', designatedpoint_wlzccb.nil_reason,
    'title', designatedpoint_wlzccb.simple_link_title) AS iaf_fix_designated_point,
    -- composed NavaidPropertyType for iaf_navaid_system,
    jsonb_build_object('href', navaid_eagkql.href,
    'nilreason', navaid_eagkql.nil_reason,
    'title', navaid_eagkql.simple_link_title) AS iaf_navaid_system,
    -- composed TouchDownLiftOffPropertyType for iaf_aiming_point,
    jsonb_build_object('href', touchdownliftoff_dqvuxd.href,
    'nilreason', touchdownliftoff_dqvuxd.nil_reason,
    'title', touchdownliftoff_dqvuxd.simple_link_title) AS iaf_aiming_point,
    -- composed RunwayCentrelinePointPropertyType for iaf_runway_point,
    jsonb_build_object('href', runwaycentrelinepoint_hgcbyt.href,
    'nilreason', runwaycentrelinepoint_hgcbyt.nil_reason,
    'title', runwaycentrelinepoint_hgcbyt.simple_link_title) AS iaf_runway_point,
    -- composed AirportHeliportPropertyType for iaf_airport_reference_point,
    jsonb_build_object('href', airportheliport_mazbpq.href,
    'nilreason', airportheliport_mazbpq.nil_reason,
    'title', airportheliport_mazbpq.simple_link_title) AS iaf_airport_reference_point,
    -- composed InstrumentApproachProcedurePropertyType for approach_rnav,
    jsonb_build_object('href', instrumentapproachprocedure_rvdphn.href,
    'nilreason', instrumentapproachprocedure_rvdphn.nil_reason,
    'title', instrumentapproachprocedure_rvdphn.simple_link_title) AS approach_rnav,
    -- composed TerminalArrivalAreaSectorPropertyType for sector,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from procedure.trmnlarrvlartmslctp_sctr_link join aixm.aixm_property on procedure.trmnlarrvlartmslctp_sctr_link.sector_hjid = aixm.aixm_property.hjid where procedure.terminalarrivalarea_t.hjid = procedure.trmnlarrvlartmslctp_sctr_link.terminalarrivalarea_t_hjid ) as sector,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from procedure.trmnlarrvlartmslctp_annttn_link join aixm.aixm_property on procedure.trmnlarrvlartmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where procedure.terminalarrivalarea_t.hjid = procedure.trmnlarrvlartmslctp_annttn_link.terminalarrivalarea_t_hjid ) as annotation
from aixm.aixm_feature
inner join procedure.terminalarrivalarea_f on aixm.aixm_feature.hjid = procedure.terminalarrivalarea_f.hjid
inner join procedure.terminalarrivalarea_tp on aixm.aixm_feature.hjid = procedure.terminalarrivalarea_tp.timeslice_hjid
inner join procedure.terminalarrivalarea_t on procedure.terminalarrivalarea_tp.terminalarrivalareatimeslice_hjid = procedure.terminalarrivalarea_t.hjid
inner join aixm.aixm_timeslice on procedure.terminalarrivalarea_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed DesignatedPointPropertyType for if_fix_designated_point
left join procedure.trmnlarrvlartmslctp_iffxdsgntdpnt_link procedure_jjwxtq on procedure.terminalarrivalarea_t.hjid = procedure_jjwxtq.terminalarrivalarea_t_hjid
left join navaids_point.designatedpoint_p designatedpoint_lujols on procedure_jjwxtq.iffixdesignatedpoint_hjid = designatedpoint_lujols.hjid
-- composed NavaidPropertyType for if_navaid_system
left join procedure.trmnlarrvlartmslctp_ifnvdsstm_link procedure_nchvxu on procedure.terminalarrivalarea_t.hjid = procedure_nchvxu.terminalarrivalarea_t_hjid
left join navaids_point.navaid_p navaid_mrbdps on procedure_nchvxu.ifnavaidsystem_hjid = navaid_mrbdps.hjid
-- composed TouchDownLiftOffPropertyType for if_aiming_point
left join procedure.trmnlarrvlartmslctp_ifamngpnt_link procedure_nhzuoy on procedure.terminalarrivalarea_t.hjid = procedure_nhzuoy.terminalarrivalarea_t_hjid
left join airport_heliport.touchdownliftoff_p touchdownliftoff_wsnmox on procedure_nhzuoy.ifaimingpoint_hjid = touchdownliftoff_wsnmox.hjid
-- composed RunwayCentrelinePointPropertyType for if_runway_point
left join procedure.trmnlarrvlartmslctp_ifrnwpnt_link procedure_efftdf on procedure.terminalarrivalarea_t.hjid = procedure_efftdf.terminalarrivalarea_t_hjid
left join airport_heliport.runwaycentrelinepoint_p runwaycentrelinepoint_zlbgtd on procedure_efftdf.ifrunwaypoint_hjid = runwaycentrelinepoint_zlbgtd.hjid
-- composed AirportHeliportPropertyType for if_airport_reference_point
left join procedure.trmnlarrvlartmslctp_ifarprtrfrncpnt_link procedure_abogih on procedure.terminalarrivalarea_t.hjid = procedure_abogih.terminalarrivalarea_t_hjid
left join airport_heliport.airportheliport_p airportheliport_qjefwr on procedure_abogih.ifairportreferencepoint_hjid = airportheliport_qjefwr.hjid
-- composed AIXMPointPropertyType for if_position
left join procedure.trmnlarrvlartmslctp_ifpstn_link procedure_sauotw on procedure.terminalarrivalarea_t.hjid = procedure_sauotw.terminalarrivalarea_t_hjid
left join gml.aixm_point_pt_view aixm_point_pt_view_hvfavo on procedure_sauotw.ifposition_hjid = aixm_point_pt_view_hvfavo.hjid
-- composed DesignatedPointPropertyType for iaf_fix_designated_point
left join procedure.trmnlarrvlartmslctp_iaffxdsgntdpnt_link procedure_srlnac on procedure.terminalarrivalarea_t.hjid = procedure_srlnac.terminalarrivalarea_t_hjid
left join navaids_point.designatedpoint_p designatedpoint_wlzccb on procedure_srlnac.iaffixdesignatedpoint_hjid = designatedpoint_wlzccb.hjid
-- composed NavaidPropertyType for iaf_navaid_system
left join procedure.trmnlarrvlartmslctp_iafnvdsstm_link procedure_qvqtbi on procedure.terminalarrivalarea_t.hjid = procedure_qvqtbi.terminalarrivalarea_t_hjid
left join navaids_point.navaid_p navaid_eagkql on procedure_qvqtbi.iafnavaidsystem_hjid = navaid_eagkql.hjid
-- composed TouchDownLiftOffPropertyType for iaf_aiming_point
left join procedure.trmnlarrvlartmslctp_iafamngpnt_link procedure_dcaqkz on procedure.terminalarrivalarea_t.hjid = procedure_dcaqkz.terminalarrivalarea_t_hjid
left join airport_heliport.touchdownliftoff_p touchdownliftoff_dqvuxd on procedure_dcaqkz.iafaimingpoint_hjid = touchdownliftoff_dqvuxd.hjid
-- composed RunwayCentrelinePointPropertyType for iaf_runway_point
left join procedure.trmnlarrvlartmslctp_iafrnwpnt_link procedure_btwjzh on procedure.terminalarrivalarea_t.hjid = procedure_btwjzh.terminalarrivalarea_t_hjid
left join airport_heliport.runwaycentrelinepoint_p runwaycentrelinepoint_hgcbyt on procedure_btwjzh.iafrunwaypoint_hjid = runwaycentrelinepoint_hgcbyt.hjid
-- composed AirportHeliportPropertyType for iaf_airport_reference_point
left join procedure.trmnlarrvlartmslctp_iafarprtrfrncpnt_link procedure_vwacox on procedure.terminalarrivalarea_t.hjid = procedure_vwacox.terminalarrivalarea_t_hjid
left join airport_heliport.airportheliport_p airportheliport_mazbpq on procedure_vwacox.iafairportreferencepoint_hjid = airportheliport_mazbpq.hjid
-- composed AIXMPointPropertyType for iaf_position
left join procedure.trmnlarrvlartmslctp_iafpstn_link procedure_gjyhon on procedure.terminalarrivalarea_t.hjid = procedure_gjyhon.terminalarrivalarea_t_hjid
left join gml.aixm_point_pt_view aixm_point_pt_view_nqthuv on procedure_gjyhon.iafposition_hjid = aixm_point_pt_view_nqthuv.hjid
-- composed AIXMSurfacePropertyType for buffer
left join procedure.trmnlarrvlartmslctp_bffr_link procedure_qetttn on procedure.terminalarrivalarea_t.hjid = procedure_qetttn.terminalarrivalarea_t_hjid
left join gml.aixm_surface_pt_view aixm_surface_pt_view_wsbkjn on procedure_qetttn.buffer_hjid = aixm_surface_pt_view_wsbkjn.hjid
-- composed InstrumentApproachProcedurePropertyType for approach_rnav
left join procedure.trmnlarrvlartmslctp_apprchrnav_link procedure_gohwhx on procedure.terminalarrivalarea_t.hjid = procedure_gohwhx.terminalarrivalarea_t_hjid
left join procedure.instrumentapproachprocedure_p instrumentapproachprocedure_rvdphn on procedure_gohwhx.approachrnav_hjid = instrumentapproachprocedure_rvdphn.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;;

--airport_heliport.touchdownliftofflightsystem_view

create or replace view airport_heliport.touchdownliftofflightsystem_view as
select distinct on (aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number)
    uuid_generate_v5 ('6ba7b810-9dad-11d1-80b4-00c04fd430c8'::uuid, aixm.aixm_feature.hjid::text || '_' || aixm.aixm_timeslice.hjid::text) row,
    aixm.aixm_message.hjid as message_hjid,
    aixm.aixm_message.id as message_id,
    aixm.aixm_message.identifier as message_tidentifier,
    aixm.aixm_feature.hjid,
    aixm.aixm_feature.id as feature_id,
    aixm.aixm_feature.identifier,
    aixm.aixm_timeslice.id as timeslice_id,
    aixm.aixm_timeslice.hjid as timeslice_hjid,
    aixm.aixm_timeslice.interpretation,
    aixm.aixm_timeslice.sequence_number,
    aixm.aixm_timeslice.correction_number,
    aixm.aixm_timeslice.feature_lifetime_begin,
    aixm.aixm_timeslice.feature_lifetime_end,
    aixm.aixm_timeslice.valid_time_begin,
    COALESCE(aixm.aixm_timeslice.valid_time_end, '2100-01-01T00:00:00Z') AS valid_time_end,
    -- embedded CodeYesNoType for getemergencylightingitem,
    airport_heliport.touchdownliftofflightsystem_t.emergencylighting::text,
    airport_heliport.touchdownliftofflightsystem_t.emergencylightingnilreason::text,
    -- embedded CodeLightIntensityType for getintensitylevelitem,
    airport_heliport.touchdownliftofflightsystem_t.intensitylevel::text,
    airport_heliport.touchdownliftofflightsystem_t.intensitylevelnilreason::text,
    -- embedded CodeColourType for getcolouritem,
    airport_heliport.touchdownliftofflightsystem_t.colour::text,
    airport_heliport.touchdownliftofflightsystem_t.colournilreason::text,
    -- embedded CodeTLOFSectionType for getpositionitem,
    airport_heliport.touchdownliftofflightsystem_t.position::text,
    airport_heliport.touchdownliftofflightsystem_t.positionnilreason::text,
    -- composed TouchDownLiftOffPropertyType for lighted_touch_down_lift_off,
    jsonb_build_object('href', touchdownliftoff_tsphly.href,
    'nilreason', touchdownliftoff_tsphly.nil_reason,
    'title', touchdownliftoff_tsphly.simple_link_title) AS lighted_touch_down_lift_off,
