--organisation.unit_view

create or replace view organisation.unit_view as
select distinct on (aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number)
    uuid_generate_v5 ('6ba7b810-9dad-11d1-80b4-00c04fd430c8'::uuid, aixm.aixm_feature.hjid::text || '_' || aixm.aixm_timeslice.hjid::text) row,
    aixm.aixm_message.hjid as message_hjid,
    aixm.aixm_message.id as message_id,
    aixm.aixm_message.identifier as message_tidentifier,
    aixm.aixm_feature.hjid,
    aixm.aixm_feature.id as feature_id,
    aixm.aixm_feature.identifier,
    aixm.aixm_timeslice.id as timeslice_id,
    aixm.aixm_timeslice.hjid as timeslice_hjid,
    aixm.aixm_timeslice.interpretation,
    aixm.aixm_timeslice.sequence_number,
    aixm.aixm_timeslice.correction_number,
    aixm.aixm_timeslice.feature_lifetime_begin,
    aixm.aixm_timeslice.feature_lifetime_end,
    aixm.aixm_timeslice.valid_time_begin,
    COALESCE(aixm.aixm_timeslice.valid_time_end, '2100-01-01T00:00:00Z') AS valid_time_end,
    -- embedded TextNameType for getaixmnameitem,
    organisation.unit_t.name::text,
    organisation.unit_t.namenilreason::text,
    -- embedded CodeUnitType for gettypeitem,
    organisation.unit_t.type::text,
    organisation.unit_t.typenilreason::text,
    -- embedded CodeYesNoType for getcomplianticaoitem,
    organisation.unit_t.complianticao::text,
    organisation.unit_t.complianticaonilreason::text,
    -- embedded CodeOrganisationDesignatorType for getdesignatoritem,
    organisation.unit_t.designator::text,
    organisation.unit_t.designatornilreason::text,
    -- embedded CodeMilitaryOperationsType for getmilitaryitem,
    organisation.unit_t.military::text,
    organisation.unit_t.militarynilreason::text,
    -- composed geometry AIXMElevatedPointPropertyType for position,
    aixm_elevated_point_pt_view_siyhiv.geom as position_geom,
    jsonb_build_object('hjid', aixm_elevated_point_pt_view_siyhiv.hjid,
    'id', aixm_elevated_point_pt_view_siyhiv.id,
    'horizontalaccuracy', aixm_elevated_point_pt_view_siyhiv.horizontalaccuracy,
    'horizontalaccuracy_uom', aixm_elevated_point_pt_view_siyhiv.horizontalaccuracy_uom,
    'horizontalaccuracy_nilreason', aixm_elevated_point_pt_view_siyhiv.horizontalaccuracy_nilreason,
    'geoidundulation', aixm_elevated_point_pt_view_siyhiv.geoidundulation,
    'geoidundulation_uom', aixm_elevated_point_pt_view_siyhiv.geoidundulation_uom,
    'geoidundulation_nilreason', aixm_elevated_point_pt_view_siyhiv.geoidundulation_nilreason,
    'verticalaccuracy', aixm_elevated_point_pt_view_siyhiv.verticalaccuracy,
    'verticalaccuracy_uom', aixm_elevated_point_pt_view_siyhiv.verticalaccuracy_uom,
    'verticalaccuracy_nilreason', aixm_elevated_point_pt_view_siyhiv.verticalaccuracy_nilreason,
    'elevation', aixm_elevated_point_pt_view_siyhiv.elevation,
    'elevation_uom', aixm_elevated_point_pt_view_siyhiv.elevation_uom,
    'elevation_nilreason', aixm_elevated_point_pt_view_siyhiv.elevation_nilreason) AS position,
    -- composed AirportHeliportPropertyType for airport_location,
    jsonb_build_object('href', airportheliport_lammqy.href,
    'nilreason', airportheliport_lammqy.nil_reason,
    'title', airportheliport_lammqy.simple_link_title) AS airport_location,
    -- composed OrganisationAuthorityPropertyType for owner_organisation,
    jsonb_build_object('href', organisationauthority_mchqnm.href,
    'nilreason', organisationauthority_mchqnm.nil_reason,
    'title', organisationauthority_mchqnm.simple_link_title) AS owner_organisation,
    -- composed ContactInformationPropertyType for contact,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from organisation.unttmslctp_cntct_link join aixm.aixm_property on organisation.unttmslctp_cntct_link.contact_hjid = aixm.aixm_property.hjid where organisation.unit_t.hjid = organisation.unttmslctp_cntct_link.unit_t_hjid ) as contact,
    -- composed UnitDependencyPropertyType for related_unit,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from organisation.unttmslctp_rltdunt_link join aixm.aixm_property on organisation.unttmslctp_rltdunt_link.relatedunit_hjid = aixm.aixm_property.hjid where organisation.unit_t.hjid = organisation.unttmslctp_rltdunt_link.unit_t_hjid ) as related_unit,
    -- composed UnitAvailabilityPropertyType for availability,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from organisation.unttmslctp_avlblt_link join aixm.aixm_property on organisation.unttmslctp_avlblt_link.availability_hjid = aixm.aixm_property.hjid where organisation.unit_t.hjid = organisation.unttmslctp_avlblt_link.unit_t_hjid ) as availability,
    -- composed NotePropertyType for annotation,
    (select coalesce(jsonb_agg(jsonb_build_object('hjid', aixm.aixm_property.hjid,
    'nilreason', aixm.aixm_property.nil_reason)),'[]'::jsonb) from organisation.unttmslctp_annttn_link join aixm.aixm_property on organisation.unttmslctp_annttn_link.annotation_hjid = aixm.aixm_property.hjid where organisation.unit_t.hjid = organisation.unttmslctp_annttn_link.unit_t_hjid ) as annotation
from aixm.aixm_feature
inner join organisation.unit_f on aixm.aixm_feature.hjid = organisation.unit_f.hjid
inner join organisation.unit_tp on aixm.aixm_feature.hjid = organisation.unit_tp.timeslice_hjid
inner join organisation.unit_t on organisation.unit_tp.unittimeslice_hjid = organisation.unit_t.hjid
inner join aixm.aixm_timeslice on organisation.unit_t.hjid = aixm.aixm_timeslice.hjid
inner join aixm.message_member on aixm.aixm_feature.hjid = aixm.message_member.feature_hjid
inner join aixm.message_member_link on aixm.message_member.hjid = aixm.message_member_link.member_hjid
inner join aixm.aixm_message on aixm.message_member_link.message_hjid = aixm.aixm_message.hjid
-- composed AIXMElevatedPointPropertyType for position
left join organisation.unttmslctp_pstn_link organisation_ascbnn on organisation.unit_t.hjid = organisation_ascbnn.unit_t_hjid
left join gml.aixm_elevated_point_pt_view aixm_elevated_point_pt_view_siyhiv on organisation_ascbnn.position_hjid = aixm_elevated_point_pt_view_siyhiv.hjid
-- composed AirportHeliportPropertyType for airport_location
left join organisation.unttmslctp_arprtlctn_link organisation_rmudea on organisation.unit_t.hjid = organisation_rmudea.unit_t_hjid
left join airport_heliport.airportheliport_p airportheliport_lammqy on organisation_rmudea.airportlocation_hjid = airportheliport_lammqy.hjid
-- composed OrganisationAuthorityPropertyType for owner_organisation
left join organisation.unttmslctp_ownrorgnstn_link organisation_tltclb on organisation.unit_t.hjid = organisation_tltclb.unit_t_hjid
left join organisation.organisationauthority_p organisationauthority_mchqnm on organisation_tltclb.ownerorganisation_hjid = organisationauthority_mchqnm.hjid
order by aixm.aixm_feature.identifier, aixm.aixm_timeslice.sequence_number desc, aixm.aixm_timeslice.correction_number desc;;

